export const voyagePlaces = {"ru-b0122c31eb1c-o0d690c69b82a":{"name":"Ресторан-Музей «ТиманЪ»","kind":"food","lat":67.63734,"lon":53.01523,"text":"Находится на въезде в центральный микрорайон города. Собственная пивоварня, кухня народов Севера","title":"Нарьян-Мар","revision":761686,"license":"CC BY-SA 4.0","image":null},"ru-aedb1d404877-o75eb6f67ce4c":{"name":"Кафе «Славянское»","kind":"coffee","lat":57.4816,"lon":60.2207,"text":"Простенькое кафе с блюдами русской кухни; есть отдельный чайный зал, где можно посидеть с десертом и кофе. Хорошие отзывы.","title":"Невьянск","revision":661142,"license":"CC BY-SA 4.0","image":null},"nn-o17557bf40375":{"name":"Арсенал","kind":"museum","lat":56.3281643,"lon":44.0064361,"text":"Бывший оружейный склад Нижегородского кремля, переделанный под современный выставочный зал. Здесь можно интересно провести время за выставками современного искусства, пообщаться с интересными людьми и провести время в кафе. Идеально подходит для любителей лофта.","title":"Нижний Новгород/Центр","revision":594955,"license":"CC BY-SA 4.0","image":"Кремль арсенал.jpg"},"nn-o176438fb3f53":{"name":"Чкаловская лестница","kind":"architecture","lat":56.330833,"lon":44.009444,"text":"Лестница, соединяющая Верхне-Волжскую и Нижне-Волжскую набережные. Является одной из визитных карточек города. Красива тем, что выполнена в виде цифры 8 и очень огромна. Никому так и не удалось сосчитать количество ступенек на ней.","title":"Нижний Новгород/Центр","revision":594955,"license":"CC BY-SA 4.0","image":"Nizhny Novgorod. Chkalov Stairs 2014.jpg"},"nn-o91b270e4b410":{"name":"Усадьба Рукавишниковых","kind":"museum","lat":56.329314,"lon":44.016246,"text":"Главный дворец Нижнего Новгорода. Усадьба купца С. М. Рукавишникова построена в 1875—1877 годах по проекту архитектора П. С. Бойцова. Усадьба содержалась в прекрасном состоянии и первым из нижегородских домов была оборудована электрическим светом в 1903 году. После революции дом был в 1918 году национализирован и в 1924 году отдан под краеведческий музей.","title":"Нижний Новгород","revision":761645,"license":"CC BY-SA 4.0","image":"Дом В.М. Рукавишникова Нижний 1.jpg"},"nn-o9c0838acd24a":{"name":"Нижегородская ярмарка","kind":"theater","lat":56.328433,"lon":43.960931,"text":"Крупнейшая ярмарка России, слава которой гремела далеко за её пределами. Неоднократно посещалась российскими императорами, а также рядом весьма любопытных персонажей, например Льюисом Кэроллом. Современная ярмарка представляет собой Главный ярмарочный дом и несколько торговых павильонов. Здесь регулярно проходят выставки, бизнес-встречи и сезонные ярмарки.","title":"Нижний Новгород","revision":761645,"license":"CC BY-SA 4.0","image":"NN Trade Fair 08-2016 img2.jpg"},"nn-o5de68667bdd2":{"name":"Та самая шаурма на Средном","kind":"food","lat":56.3097,"lon":43.991,"text":"Пожалуй, лучшая кебабная Нижнего Новгорода. Об этом можно судить и по постоянным очередям за шаурмой, и по проверке телепередачей «Ревизорро». Идеально подходит для петербуржцев, чтобы сравнить шаурму и шаверму. Среди нижегородцев даже есть такая шутка: �«Не пробовал шаурмы со Средного — Нижнего не видел».","title":"Нижний Новгород","revision":761645,"license":"CC BY-SA 4.0","image":null},"ru-b28b6f6f1435-o4489ba880f08":{"name":"Новокузнецкий драматический театр","kind":"theater","lat":53.75728,"lon":87.12087,"text":"один из старейших театров Кузбасса, театр открылся 6 ноября 1933 г. В 1963 г. для театра было построено нынешнее здание в имперском классическом стиле.","title":"Новокузнецк","revision":689422,"license":"CC BY-SA 4.0","image":null},"ru-140e31da27bf-o37f63255b6f6":{"name":"Тобольские ворота","kind":"architecture","lat":54.985185,"lon":73.362554,"text":"Тобольские ворота — западные ворота крепости. Они были построены в 1771—73 годах, и это самое старое сохранившееся здание Омска. Это также единственные сохранившиеся ворота крепости, остальные были снесены и позже реконструированы. Изначальные ворота были барочными, а в середине XIX века их перестроили в стиле классицизма. По бокам сохранились контрфорсы.","title":"Омск","revision":633554,"license":"CC BY-SA 4.0","image":"Tobolsk Gate2.JPG"},"ru-140e31da27bf-occb58d6bd360":{"name":"Тарские ворота","kind":"architecture","lat":54.987704,"lon":73.367999,"text":"Тарские ворота — северные ворота крепости. Построены в 1792 году, название, как и улицы — от города Тара ниже по Иртышу. Разобраны в 1959 году, восстановлены в 1991 году.","title":"Омск","revision":633554,"license":"CC BY-SA 4.0","image":"Tara Gate Omsk.jpg"},"ru-0f2f2d098e7a-o4396a48122c8":{"name":"Хинкальная","kind":"food","lat":55.8095,"lon":38.9795,"text":"Ресторан грузинской кухни, где стены обшиты брёвнами словно в русской избе. Десяток разновидностей хинкали, несколько видов хачапури, шашлык и все стандартные блюда грузинской кухни, подаваемые с пылу с жару в глиняных горшочках. Уютно.","title":"Орехово-Зуево","revision":766113,"license":"CC BY-SA 4.0","image":null},"ru-2abed4d95565-o6c88a5813fa0":{"name":"Трактир «ПельменовЪ»","kind":"food","lat":52.973045,"lon":36.064753,"text":"Широкий выбор пельменей и блюд русской кухни по демократичным ценам, недалеко от площади Ленина.","title":"Орёл","revision":732299,"license":"CC BY-SA 4.0","image":null},"ru-2abed4d95565-oc34f002345a2":{"name":"Ресторан «Честер Паб»","kind":"food","lat":52.958907,"lon":36.065324,"text":"Престижный пивной ресторан, предлагающий помимо пивных закусок стейки, гриль, салаты, супы и морепродукты. Интерьеры оформлены под английский паб.","title":"Орёл","revision":732299,"license":"CC BY-SA 4.0","image":null},"ru-7baaac39aa31-o5965ba02350b":{"name":"Дом енота","kind":"architecture","lat":56.2645,"lon":37.9998,"text":"Частный коттедж, превращённый в енотовый питомник. Хозяева проводят экскурсии и дают поиграть с животными, хотя предупреждают об их непредсказуемом хулиганском характере. Только по предварительной записи.","title":"Абрамцево","revision":749052,"license":"CC BY-SA 4.0","image":null},"ru-d13945a87017-o67a3284b1917":{"name":"Кинотеатр «Мир»","kind":"family","lat":53.34916,"lon":83.76319,"text":"Кинозал соседствует с увеселительными заведениями, шум из которых мешает просмотру кино.","title":"Барнаул","revision":767888,"license":"CC BY-SA 4.0","image":"Barnaul-Mir1.JPG"},"ru-d13945a87017-of7ea9ef84693":{"name":"Место пасты","kind":"coffee","lat":53.33757,"lon":83.78667,"text":"Уютный ресторанчик с итальянским оттенком. Кроме пиццы и пасты небольшой ассортимент салатов и горячих блюд.","title":"Барнаул","revision":767888,"license":"CC BY-SA 4.0","image":null},"ru-d13945a87017-ocf3f6c878034":{"name":"Renoir Coffee","kind":"coffee","lat":53.33384,"lon":83.79318,"text":"Самая пижонская кофейня Барнаула хочет, «чтобы в важные моменты вашей жизни вы пили отличный кофе». На практике это означает, что под стать моменту вы можете выбрать сорт зёрен, степень обжарки и способ заваривания — например, классический по пути на работу и пуровер по выходным.","title":"Барнаул","revision":767888,"license":"CC BY-SA 4.0","image":null},"ru-02e9c019ab4d-o0c9bbfc6c09c":{"name":"Ресторан «Башня»","kind":"food","lat":50.598071,"lon":36.582584,"text":"Основной интерес представляет здание ресторана, выполненного в виде точной копии Московской сторожевой башни, бывшей в XVII-XVIII веках главной башней белгородского кремля. Окружает башню насыпной земляной вал. Кулинарные возможности ресторана много скромнее, еда не особо вкусная. Пафосно и неуютно. В тёплое время года работает летняя веранда.","title":"Белгород","revision":761357,"license":"CC BY-SA 4.0","image":null},"ru-deb1d05a71ce-o5fe405cae140":{"name":"Мамины блины","kind":"coffee","lat":56.84622,"lon":53.20012,"text":"Типовой провинциальный фаст-фуд, предлагающий блины с разнообразными начинками, а также скромный выбор разогреваемых супов и завёрнутых в плёнку салатов. Чисто, аккуратно.","title":"Ижевск","revision":751163,"license":"CC BY-SA 4.0","image":null},"ru-8eeed22272e7-oca87698fe58f":{"name":"Московские ворота","kind":"architecture","lat":52.2936,"lon":104.28617,"text":"Основаная достопримечательность нижней набережной, исторический памятник, снесённый в 1911 г. и вновь воссозданный в 2011 г. к 350-летию Иркутска. Изначально ворота были построены в 1813 году в честь десятилетия восшествия на престол Александра I.","title":"Иркутск","revision":731562,"license":"CC BY-SA 4.0","image":"Иркутск. Московские ворота.JPG"},"ru-8d0a05bf3b8a-o87444d017f86":{"name":"Здание присутственных мест","kind":"museum","lat":58.5206,"lon":31.274823,"text":"Архитектурный памятник классицизма, построенный в 1780-ых годах по проекту архитектора В.С. Поливанова, встречает посетителей парой бронзовых львов. Помещения первого этажа озадачивают сводчатыми потолками, выполненными в духе XVII века. Когда-то здесь размещалась губернская администрация, где в 1842-1842 годах служил сосланный в Новгород А.И. Герцен.","title":"Великий Новгород","revision":712875,"license":"CC BY-SA 4.0","image":"VNovgordDetinets GovermentOffice 4418.JPG"},"ru-8d0a05bf3b8a-o03360e0dc90b":{"name":"Десятинный монастырь","kind":"architecture","lat":58.517883,"lon":31.265347,"text":"Старинный монастырь был основан в XIII веке матерью Александра Невского, по легенде, на том самом месте, где в 1170 году новгородцы разбили суздальское войско.","title":"Великий Новгород","revision":712875,"license":"CC BY-SA 4.0","image":"Десятинный монастырь.jpg"},"ru-8d0a05bf3b8a-o4eccc4223730":{"name":"Ярославово дворище","kind":"museum","lat":58.51865,"lon":31.28469,"text":"– участок между Волховым и Большой Московской улицей, где на небольшой площади расположены целых семь древних церквей. Пять из них стоят в непосредственной близости, а две другие чуть поодаль – по другую сторону от улицы Ильина. В древности где-то тут находилась резиденция Ярослава Мудрого, собственно, и давшая название этой территории.","title":"Великий Новгород","revision":712875,"license":"CC BY-SA 4.0","image":"Yaroslavovo Dvorische 01.jpg"},"ru-8d0a05bf3b8a-o50a6d5b79687":{"name":"Церковь Федора Стратилата на Ручью","kind":"architecture","lat":58.523342,"lon":31.293048,"text":"Как написано на памятной табличке, церковь построена в 1360-1361 годах по заказу посадника Василия Даниловича. По другим данным, заказчиком был посадник Семен Андреевич со своей матерью Натальей. Во второй части названия церкви – «на Ручью» – сохранилась память о засыпанном в XX веке Фёдоровском ручье, давшем название возникшей на его месте улице.","title":"Великий Новгород","revision":712875,"license":"CC BY-SA 4.0","image":"VNovgorod StTheodoreStratelatesBrook VN139.jpg"},"ru-8d0a05bf3b8a-od999ed6d9a66":{"name":"Новгородская областная филармония","kind":"theater","lat":58.521845,"lon":31.274981,"text":"В филармонии течёт на удивление бурная музыкальная жизнь, особенно для небольшого областного центра, каким является Новгород. Концерты классической и эстрадной музыки 2-3 раза в неделю.","title":"Великий Новгород","revision":712875,"license":"CC BY-SA 4.0","image":null},"ru-ca091eae2c39-oca7666c13d0c":{"name":"Памятник Александру Матросову","kind":"architecture","lat":56.34510159022225,"lon":30.509261784567062,"text":"В 1943 году Александр Матросов бросился на амбразуру врага, ему было всего 19 лет. Четырехметровая статуя бегущего Героя Советского Союза установлена в Петровском парке. На постаменте — информативная надпись; в 30 метрах горит вечный огонь.","title":"Великие Луки","revision":605166,"license":"CC BY-SA 4.0","image":null},"ru-f66a00e6179e-od9fbfa2fb3a3":{"name":"Центральный парк культуры и отдыха","kind":"park","lat":56.141569,"lon":40.411813,"text":"Открыт в 1959 г., до этого на этом месте в 1957 г. построили выставочный комплекс из 12 павильонов (\"Владимирская ВДНХ\"), многие из которых сохранились. В парке находится колесо обозрения «Небо33».","title":"Владимир","revision":632909,"license":"CC BY-SA 4.0","image":null},"ru-f66a00e6179e-o410902ebc578":{"name":"Владимирский областной театр кукол","kind":"theater","lat":56.12996,"lon":40.40315,"text":"По вечерам в здании театра кукол работает обычный театр с преимущественно комедийными постановками.","title":"Владимир","revision":632909,"license":"CC BY-SA 4.0","image":"Vladimir asv2019-01 img15 Puppet Theater.jpg"},"ru-7b6de6a586d0-o83343dd0837e":{"name":"Английская пекарня Five o'clock","kind":"coffee","lat":43.11759,"lon":131.88151,"text":"Неизвестно, что же здесь английского, хотя чай с молоком вроде бы подают. Тем не менее дешёвая выпечка привлекает кучу народа. Уютный интерьер с маленькими столиками на двоих. Днём может быть тесновато.","title":"Владивосток","revision":774433,"license":"CC BY-SA 4.0","image":null},"ru-023484a5f98d-o9b36c2b79f11":{"name":"Вологодский кремль","kind":"museum","lat":59.223619,"lon":39.88216,"text":"Вологодский кремль начал строиться Иваном Грозным в 1565, как каменная крепость своей новой северной резиденции. Укреплённая территория должна была занимать площадь 46 га и находиться в пределах современных улиц Мира, Ленинградская, Октябрьская и реки Вологда – это в 2,1 раза превышало площадь превышало площадь Московского Кремля.","title":"Вологда","revision":728411,"license":"CC BY-SA 4.0","image":"Вид на Вологодский кремль.jpg"},"ru-023484a5f98d-oe9ea3a686e4c":{"name":"Софийский собор","kind":"architecture","lat":59.224389,"lon":39.882267,"text":"Древнейшее сохранившееся каменное сооружение в Вологде, построенное по образу и подобию Успенского собора Московского Кремля. Почти 60-ти метровый шестистолпный храм увенчан пятью главами, которые изначально имели шлемовидную форму.","title":"Вологда","revision":728411,"license":"CC BY-SA 4.0","image":"Saint Sophia Cathedral in Vologda 2009.jpg"},"ru-023484a5f98d-o717bda2be54d":{"name":"Колокольня Софийского собора","kind":"architecture","lat":59.224021,"lon":39.882833,"text":"78-метровая колокольня, возведённая в псевдоготическом стиле, уже пятая по счёту: первые три были деревянные — лишь в 1659 году из разобранных кремлёвский стен возвели первую каменную. Через 10 лет её верх разобрали, и на старом фундаменте построили современную, более высокую. На башне колокольни работают куранты, изготовленные в Москве в 1871 году.","title":"Вологда","revision":728411,"license":"CC BY-SA 4.0","image":"Vologda belfry.jpg"},"ru-023484a5f98d-o2e7628bdbd1c":{"name":"Вологодский драматический театр","kind":"theater","lat":59.216944,"lon":39.897517,"text":"Самый крупный театр в области, открытый в 1849 году. В современное здание театр переехал в 1974 году. Здесь можно посмотреть пьесы и оперы в диапазоне от классических до современных. Цены очень демократичные.","title":"Вологда","revision":728411,"license":"CC BY-SA 4.0","image":"Драмтеатр72.jpg"},"ru-a52b73890cfe-ob599d1073427":{"name":"Мельница Гергардта","kind":"architecture","lat":48.7156,"lon":44.53316,"text":"Здание 5-этажной паровой мельницы начала XX века, разрушенное в дни Сталинградской битвы. Одно из трёх не восстановленных как память о войне зданий. Входит в состав Музея-заповедника «Сталинградская битва». Не стоит путать с домом Павлова.","title":"Волгоград","revision":764382,"license":"CC BY-SA 4.0","image":"May2015 Volgograd img14 Gergardt Mill.jpg"},"ru-5bf5ddff6353-of5856aa3e66f":{"name":"Пролетарий","kind":"family","lat":51.66507,"lon":39.20453,"text":"Один из старейших кинотеатров города. Первое здание кинотеатра «Увечный воин» было построено в 1914-1917 годах в стиле неоклассицизма. На 4 этаже скульптурные изображения шести муз. В советское время кинотеатр переименовали, а в 1966-1969 годах с угла пристроили новый полукруглый корпус. На полукруглой стене фойе помещено мозаичное панно «Прометей».","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":"Пролетарий 2015.JPG"},"ru-5bf5ddff6353-o54eb5d8afc08":{"name":"Юность","kind":"family","lat":51.67032,"lon":39.20487,"text":"Кинотеатр построен в 1963 году. На его месте до разрушения в годы войны находился кинотеатр «Палас». В кинотеатре 2 зала, как и в Пролётке в большом зале имеются ложи.","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":null},"ru-5bf5ddff6353-o2fed095d46aa":{"name":"Воронежская филармония","kind":"live","lat":51.663137,"lon":39.203231,"text":"Здание филармонии было построено в 1908 году для второго в городе кинотеатра, называвшегося «Тауматограф».","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":"Воронежская филармония 01.JPG"},"ru-5bf5ddff6353-o19eaf84e7dea":{"name":"Воронежский концертный зал","kind":"live","lat":51.666132,"lon":39.212244,"text":"Здание концертного зала построено как замена обветшавшему драматическому театру. Однако акустика на новой сцене оказалась слабой, в итоге театр вернулся в своё историческое здание, а в этом здание организован концертный зал.","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":"Voronezhsky dramatichesky teatr 2008.jpg"},"ru-5bf5ddff6353-o5f1e5404c58c":{"name":"De Bassus","kind":"night","lat":51.667662,"lon":39.19333,"text":"Баварская кухня, собственная мини-пивоварня. Второе заведение находится в Северном на бульваре Победы.","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":null},"ru-5bf5ddff6353-od1a6d4c04b6c":{"name":"Винзавод","kind":"night","lat":51.676138,"lon":39.200992,"text":"Пространство кафе, баров и ресторанов. Находится на территории памятника архитектуры — комплекса винного завода, начала XX века.","title":"Воронеж","revision":780734,"license":"CC BY-SA 4.0","image":null},"ru-0648e41ca09b-ocf6193f4023b":{"name":"Царевококшайский кремль","kind":"architecture","lat":56.6374,"lon":47.9005,"text":"Пожалуй, кремль правильнее было бы назвать не «царевококшайским», а «йошкар-олинским»: всё же при Ноготкове-Оболенском вряд ли стали бы строить совершенно пустую внутри крепость. На стены кремля можно подняться, хотя вид на город оттуда не впечатляет. Внутри развешаны таблички о древних жителях Марий Эл, начиная с палеолита.","title":"Йошкар-Ола","revision":774292,"license":"CC BY-SA 4.0","image":"Царёвококшайский кремль.jpg"},"ru-0648e41ca09b-obe69d9e3c16c":{"name":"Марийский национальный театр драмы им. М. Шкетана","kind":"theater","lat":56.63173,"lon":47.89158,"text":"Театр ведёт свою историю с 1919 года. Здание — типичнейший образец сталинского классицизма без малейших признаков национального стиля.","title":"Йошкар-Ола","revision":774292,"license":"CC BY-SA 4.0","image":"Йошкар-Ола Марийский драматический театр 26.07.2014.jpg"},"ru-0648e41ca09b-o346a5420d1bf":{"name":"Центральный парк культуры и отдыха","kind":"park","lat":56.6365,"lon":47.8903,"text":"Находится в самом центре города, разделяя две части одного бульвара — Победы и Чавайна. В парке обычная для таких мест концентрация памятников, в том числе крупный воинский мемориал и миниатюрный памятник Ленину.","title":"Йошкар-Ола","revision":774292,"license":"CC BY-SA 4.0","image":"Ворота парка Культуры, Йошкар-Ола.jpg"},"ru-0648e41ca09b-oeccf30c89828":{"name":"Паб «Бульдог»","kind":"night","lat":56.63418,"lon":47.89916,"text":"Спорт-бар, который одновременно является главной в городе точкой продажи крафтового пива. К этому прилагается еда, не вызывающая, правда, у посетителей большого восторга.","title":"Йошкар-Ола","revision":774292,"license":"CC BY-SA 4.0","image":null},"ru-e157b9c0f908-o3f4f7ba6fb27":{"name":"Океанариум «Океан-парк»","kind":"family","lat":44.55889,"lon":38.07648,"text":"Два десятка маленьких аквариумов и замученная обезьянка собирают стабильно отрицательные отзывы.","title":"Геленджик","revision":775747,"license":"CC BY-SA 4.0","image":null},"ru-e157b9c0f908-o0e10aef1078d":{"name":"Столовая «СССР»","kind":"food","lat":44.5551,"lon":38.07287,"text":"Название немного лукавит: в советских столовых не было греческого салата и пластиковой посуды. В остальном обычная столовая: дешевая еда приемлемого качества.","title":"Геленджик","revision":775747,"license":"CC BY-SA 4.0","image":null},"ru-a309e4ce2f36-ofb33e5b08560":{"name":"Дом Мешкова","kind":"museum","lat":58.01862,"lon":56.24654,"text":"История лучших пермских строений на удивление похожа: сначала строили рядовой особняк, а потом его выкупал купец, заказывавший необычную отделку.","title":"Пермь","revision":768227,"license":"CC BY-SA 4.0","image":"Perm asv2019-05 img26 Monastyrskaya11.jpg"},"ru-a309e4ce2f36-oa1adc4462167":{"name":"Старокирпичный переулок","kind":"coffee","lat":58.0127627,"lon":56.2444103,"text":"Место, популярное у местных хипстеров и людей, которые бы хотели быть на них похожими. Так называемый арт-кластер \"Старокирпичный переулок\" не так просто найти с первого раза — для этого надо нырнуть в арку во двор со стороны улицы Ленина.","title":"Пермь","revision":768227,"license":"CC BY-SA 4.0","image":null},"spb-o3b507c76b16d":{"name":"Ресторан «Трувель»","kind":"food","lat":59.879896,"lon":29.90902,"text":"Ресторан русской и средиземноморской кухни с летним и зимним меню. Летом можно попробовать свекольник, окрошку, гаспачо, салат с печёными баклажанами и солёные грузди. По субботам проводятся музыкальные вечера.","title":"Петергоф","revision":775642,"license":"CC BY-SA 4.0","image":null},"ru-ccc344878fd4-o6f7dfbf1af2d":{"name":"Музыкальный театр Республики Карелия","kind":"theater","lat":61.7874,"lon":34.3845,"text":"Театр основан в 1955 году, открылся 5 ноября 1955 года опереттой И. Дунаевского «Вольный ветер».","title":"Петрозаводск","revision":730945,"license":"CC BY-SA 4.0","image":"Муздрамтеатр.jpg"},"ru-ccc344878fd4-o17e7dab24156":{"name":"«Культура»","kind":"food","lat":61.788738,"lon":34.3687,"text":"Хипстерское место - винный бар , играются dj-сеты. Есть фейсер. Почти ночной клуб.","title":"Петрозаводск","revision":730945,"license":"CC BY-SA 4.0","image":null},"ru-df679694d505-o6b02c5a7872d":{"name":"Закхаймские ворота","kind":"architecture","lat":54.70957,"lon":20.53816,"text":"Пересечение Московского проспекта и Литовского вала. Нижние помещения переделана в арт-кафе.","title":"Калининград","revision":750796,"license":"CC BY-SA 4.0","image":"Городские ворота Закхаймские 01.jpg"},"ru-df679694d505-o8858a35a9263":{"name":"Бранденбургские ворота","kind":"architecture","lat":54.69728,"lon":20.49468,"text":"Единственные городские ворота Калининграда, до сих пор использующиеся по прямому назначению (через них проходит проезжая часть улицы, трамвайная линия и пешеходный тротуар).","title":"Калининград","revision":750796,"license":"CC BY-SA 4.0","image":null},"ru-b502ae45897e-o0dd240c001ed":{"name":"Калужский областной драматический театр","kind":"theater","lat":54.515748,"lon":36.258637,"text":"Один из старейших действующих драматических театров России. Основан в 1777 году.","title":"Калуга","revision":739012,"license":"CC BY-SA 4.0","image":"Здание областного драматического театра.jpg"},"ru-b502ae45897e-oeaf77cc5646b":{"name":"Гриль-бар «Крылья»","kind":"food","lat":54.513662,"lon":36.265958,"text":"Кухни: пивная, европейская, русская. Гриль-меню, детское меню, коктейльная карта. 2 зала, 240 посадочных мест. Детский игровой уголок. Бесплатный Wi-Fi. Бизнес-ланч: 11:00 - 16:00.","title":"Калуга","revision":739012,"license":"CC BY-SA 4.0","image":null},"ru-14c73394b886-o7b18ff37b796":{"name":"Кофейня «Рога и копыта»","kind":"coffee","lat":57.76558,"lon":40.93134,"text":"Отличный интерьер, с ростовыми фигурами и сюжета из книг про Остапа Бендера. Вроде называется кофейня, но можно вкусно пообедать.","title":"Кострома","revision":772418,"license":"CC BY-SA 4.0","image":null},"ru-14c73394b886-o48615b02b9f6":{"name":"Траттория «Пиноккио»","kind":"food","lat":57.7629,"lon":40.94488,"text":"Ещё одно заведение, ностальгирующее по Италии. Пицца, паста, и почему-то роллы.","title":"Кострома","revision":772418,"license":"CC BY-SA 4.0","image":null},"ru-14c73394b886-ofd0a5a4bc343":{"name":"Ресторан «Белое солнце»","kind":"food","lat":57.7607,"lon":40.9306,"text":"Ресторан с кавказской, европейской и русской кухней. Интерьер по теме фильма.","title":"Кострома","revision":772418,"license":"CC BY-SA 4.0","image":null},"ru-d790c72e479b-o8fa1203c3545":{"name":"Первомайский парк","kind":"park","lat":51.729268,"lon":36.194435,"text":"Расположен в самом центре города, между Красной площадью и крутым обрывом у реки Тускарь. В конце XIX века здесь, на месте бывшей торговой площади, открыли городской сад, устроив аллеи для прогулок, фонтаны и беседки с панорамными видами на берега Тускари. Летом в саду по вечерам играл военный оркестр, а зимой заливался каток.","title":"Курск","revision":750286,"license":"CC BY-SA 4.0","image":"Курск. Первомайский парк в 2024 году.jpg"},"ru-7dfa745eaa19-o6bd1b46d347d":{"name":"Чистяковская роща","kind":"park","lat":45.0577,"lon":38.9937,"text":"Здесь расположен самый большой детский городок, веревочный парк, фонтаны и аллеи с цветниками.","title":"Краснодар","revision":775067,"license":"CC BY-SA 4.0","image":null},"ru-9b968c73f4d4-o7bffb34c874d":{"name":"Кофейня «Культура»","kind":"coffee","lat":56.0126,"lon":92.8771,"text":"Кофейня в европейском стиле. Крошечные столики — ровно такие, чтобы на них влезли две чашки кофе. Стандартный ассортимент латте, капучино и кофейных коктейлей, а также нехитрая выпечка вроде круассанов. Хотя в заведении есть Wi-Fi, работать тут неудобно, поскольку ноутбук практически свешивается со стола.","title":"Красноярск","revision":703215,"license":"CC BY-SA 4.0","image":null},"ru-c86ad06cc721-oc99b1bfddf2e":{"name":"Дом Культуры «Мир»","kind":"theater","lat":56.74904,"lon":37.18817,"text":"Регулярные выставки художников и фотографов, концерты творческих коллективов, хоров. Концертный зал ОИЯИ.","title":"Дубна","revision":731739,"license":"CC BY-SA 4.0","image":"Cultur House Dubna.JPG"},"ru-eacb5f151a2e-o9972d9613347":{"name":"Липецкий государственный академический театр драмы им. Л.Н. Толстого","kind":"theater","lat":52.605116,"lon":39.59077,"text":"Главная драматическая сцена области, основан в 1921 году. Классический и современный репертуар","title":"Липецк","revision":775972,"license":"CC BY-SA 4.0","image":null},"ru-eacb5f151a2e-of34039517475":{"name":"SV Больше Чем Бар","kind":"live","lat":52.604872,"lon":39.594486,"text":"Ночной клуб с рейтингом 4.9★. Караоке-холл, танцевальный зал, бар. Расположен в цокольном этаже в центре города","title":"Липецк","revision":775972,"license":"CC BY-SA 4.0","image":null},"ekb-oc0f56483a271":{"name":"Вечный огонь","kind":"architecture","lat":56.83576,"lon":60.57838,"text":"Екатеринбургский вариант вечного огня, расположен в парке у пл. Коммунаров.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-obd94b204fc34":{"name":"Свердловская киностудия","kind":"family","lat":56.83816,"lon":60.62392,"text":"В здании киностудии расположен развлекательный парк чудес \"Галилео\" и музей кино и мультфильмов.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-o797915f37bb6":{"name":"Екатеринбургский государственный академический театр оперы и балета","kind":"theater","lat":56.839,"lon":60.61662,"text":"Одна из архитектурных достопримечательностей - барочное здание начала XX века. Высокобюджетные постановки оперы и балета, достойная труппа. Пользуется популярностью у горожан, поэтому билеты лучше приобретать заранее.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-ob50cbee6f24d":{"name":"Свердловский государственный академический театр музыкальной комедии","kind":"theater","lat":56.83962,"lon":60.61186,"text":"Самый популярный театр Екатеринбурга - расположен в центре, репертуар (мюзиклы и оперетты) ориентирован на широкого зрителя. Билеты доставать также желательно заранее.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-o029ca389a34b":{"name":"Камерный театр","kind":"theater","lat":56.84361,"lon":60.60694,"text":"Небольшой театр с классическим репертуаром. В постановках задействованы именитые актёры из театральных трупп других театров города.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-o30552c512841":{"name":"ККТ Космос","kind":"live","lat":56.84515,"lon":60.60476,"text":"Самый большой экран города именно здесь. 3 зала (в том числе IMAX), проводятся показы стереокино.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-o512929036573":{"name":"Салют","kind":"family","lat":56.83814,"lon":60.61009,"text":"Сразу пять маленких залов помимо одного большого - это определило специфику кинотеатра: помимо мейнстрима здесь можно посмотреть всё то, что не доходит до проката мультиплексов. В прокате фестивальное, документальное кино, работы азиатских и европейских кинорежиссёров.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-odf2e69ea59f7":{"name":"Екатеринбургский зоопарк","kind":"family","lat":56.8326389,"lon":60.6217592,"text":"Более 300 видов животных, включая белых тигров, слона, медведей и т.д.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ekb-o4c83081bce81":{"name":"Дом книги","kind":"books","lat":56.8402363,"lon":60.5936405,"text":"Самый большой книжный магазин города. Здесь можно найти сувенирные издания о городе и регионе.","title":"Екатеринбург","revision":724574,"license":"CC BY-SA 4.0","image":null},"ru-988157bfd6d5-o722a12eba2ee":{"name":"Ресторан «Учкудук»","kind":"food","lat":53.41833,"lon":58.99558,"text":"Восточная кухня, понятая расширительно вплоть до грузинской, греческой и, страшно сказать, французской. Большой выбор блюд, приготовленных на тандыре, вулканическом камне по технологии Stone grill и «на гималайской соли». Интерьер в восточном стиле. Посетители сдержанно рекомендуют.","title":"Магнитогорск","revision":777472,"license":"CC BY-SA 4.0","image":null},"msk-o36f138dc6ee0":{"name":"Палаты Аверкия Кириллова","kind":"architecture","lat":55.74375,"lon":37.6101,"text":"Редкий образец жилого дома второй половины XVII — начала XVIII веков. Вместе со стоящей рядом церковью Николы на Берсеневке входит в ансамбль зданий XVII века, появившийся по воле одного заказчика – Аверкия Кириллова. Комплекс расположен в Верхних Садовниках на землях, некогда принадлежавших боярам Беклемишевым. Их последний владелец И.Н.","title":"Москва/Замоскворечье","revision":773943,"license":"CC BY-SA 4.0","image":"Фасад палат Аверкия Кириллова.jpeg"},"msk-o37b56bc8a87d":{"name":"Дом на набережной","kind":"museum","lat":55.74445,"lon":37.61245,"text":"Огромный 12-этажный дом, построенный для партийной номенклатуры в 1927-31 гг. по проекту архитектора Б. М. Иофана. Серое здание в стиле конструктивизма было для Москвы начала 1930-х не меньшим вызовом, чем памятник Петру I конца 1990-х, но с тех пор к дому на набережной давно привыкли, и он стал одной из узнаваемых московских достопримечательностей.","title":"Москва/Замоскворечье","revision":773943,"license":"CC BY-SA 4.0","image":"Moscow, Bersenevskaya Embankment 2008 02.jpg"},"msk-od5801aaaf602":{"name":"Памятник Георгию Димитрову","kind":"architecture","lat":55.739134,"lon":37.616889,"text":"Памятник известному болгарскому коммунисту и революционеру был выполнен отцом и сыном К.М и М.К. Мерабишвили и установлен в 1972 году в начале улицы Г. Димитрова – так в 1956-1992 годах называли улицу Большая Якиманка.","title":"Москва/Замоскворечье","revision":773943,"license":"CC BY-SA 4.0","image":"Moscow DimitrovMonument 8553.jpg"},"msk-o6024fb22c65e":{"name":"Шуховская башня","kind":"architecture","lat":55.71738,"lon":37.6116,"text":"Уникальная гиперболоидная конструкция, выполненная в виде несущей стальной сетчатой оболочки. Расположена в Москве на улице Шаболовка. Построена в 1919—1922 годах. Памятник архитектуры. Автор проекта и руководитель строительства радиобашни — великий русский инженер, архитектор, и учёный, академик Владимир Григорьевич Шухов (1853—1939).","title":"Москва/Замоскворечье","revision":773943,"license":"CC BY-SA 4.0","image":null},"msk-o81dbdc79ab67":{"name":"Московский международный дом музыки","kind":"live","lat":55.73332,"lon":37.64548,"text":"Дом музыки был построен в 2002 году и стал самой большой в столице концертной площадкой классической музыки. В комплекс входят три зала – Светлановский, Камерный и Театральный, а также летнее кафе, предназначенное для джазовых фестивалей и концертов популярной классической музыки.","title":"Москва/Замоскворечье","revision":773943,"license":"CC BY-SA 4.0","image":null},"ru-0d7d5d87f0a6-o700a950f051e":{"name":"Благовещенский мужской монастырь","kind":"architecture","lat":55.58242,"lon":42.05383,"text":"Монастырь был основан в 1553 г., собор 1664 г., надвратная Стефановская церковь 1716 г.","title":"Муром","revision":580675,"license":"CC BY-SA 4.0","image":null},"ru-0d7d5d87f0a6-o7033b6cfa580":{"name":"Памятник Илье Муромцу","kind":"architecture","lat":55.5805,"lon":42.0617,"text":"Памятник работы скульптора В.М. Клыкова и архитектора Н.А. Беспалова был установлен в 1999 году в городском парке им. В.И. Ленина на высоком берегу Оки.","title":"Муром","revision":580675,"license":"CC BY-SA 4.0","image":"Murom-monument.jpg"},"ru-0d7d5d87f0a6-o645affccad46":{"name":"Кафе «Витязь»","kind":"coffee","lat":55.5777,"lon":42.0529,"text":"Фиксированное меню, комплексные обеды, европейская и японская кухня. Идеальное место, чтобы перекусить в любое время дня. Доступ в ТЦ закрывается в 19:30.","title":"Муром","revision":580675,"license":"CC BY-SA 4.0","image":null},"ru-b7127184ead6-oa5e2442ce549":{"name":"Атомный ледокол «Ленин»","kind":"museum","lat":68.9756,"lon":33.0599,"text":"Атомный ледокол «Ленин» – первое в мире надводное судно с ядерной силовой установкой, построен в СССР, на судостроительном заводе в Ленинграде. Веден в эксплуатацию в 1959 году. Корабль проработал 30 лет и в 1989 году был поставлен на вечную стоянку в Мурманске. В 2009 году начались работы по преобразованию судна в музей.","title":"Мурманск","revision":783326,"license":"CC BY-SA 4.0","image":null},"ru-b7127184ead6-o13f767420ee0":{"name":"Юность","kind":"coffee","lat":68.9721329,"lon":33.0807995,"text":"Одно из старейших и известнейших заведений общепита в городе. Вкусные десерты и выпечка, в том числе с северной - морошковой начинкой. Однако, проверку Ревизорро заведение не прошло.","title":"Мурманск","revision":783326,"license":"CC BY-SA 4.0","image":null},"ru-5f290be714ff-o537536c72e17":{"name":"Федеральное военное мемориальное кладбище","kind":"architecture","lat":55.927,"lon":37.6756,"text":"Открытый в 2013 году некрополь для лиц, имеющих особые заслуги перед государством. Свободного посещения нет, но иногда проводятся экскурсии.","title":"Мытищи","revision":765471,"license":"CC BY-SA 4.0","image":null},"ru-44388ad006aa-odc35ab3fd94f":{"name":"Сахалинский театр кукол","kind":"theater","lat":46.96002,"lon":142.74131,"text":"Хороший детский театр, известный за пределами Сахалина. Взрослым здесь может быть скучновато, но в отсутствие иной театральной жизни даже детский спектакль становится развлечением.","title":"Южно-Сахалинск","revision":774438,"license":"CC BY-SA 4.0","image":null},"ru-292c0a6a47ce-o0ca709627be1":{"name":"Памятник водопроводчику","kind":"architecture","lat":58.0512,"lon":38.84714,"text":"Скульптура водопроводчика у местного «Водоканала», по пояс высунувшегося из люка с разводным ключом. Находится сразу за забором и может быть недоступен в нерабочие дни, но через забор хорошо видно.","title":"Рыбинск","revision":743594,"license":"CC BY-SA 4.0","image":null},"ru-292c0a6a47ce-o386814d420a9":{"name":"Памятник бурлаку","kind":"architecture","lat":58.04985,"lon":38.85418,"text":"Скульптура находится в парковой зоне на Волжской набережной, у старой «хлебной» (лоцманской) биржи. Она установлена в 1977 году к 200-летию города.","title":"Рыбинск","revision":743594,"license":"CC BY-SA 4.0","image":null},"ru-86e5bae4ef58-o5c9d7b0ab0ff":{"name":"Кухмистерская «Хлебная площадь»","kind":"food","lat":54.62978,"lon":39.73598,"text":"«Музей-ресторан» на стыке дворянской и советской стилистики. Меню тоже разбито на две части — «старорежимного порядка» и «пролетарского периода».","title":"Рязань","revision":747195,"license":"CC BY-SA 4.0","image":null},"ru-dd8caeabc685-oe5ff474a3f2b":{"name":"Чувашский государственный театр оперы и балета","kind":"theater","lat":56.14456,"lon":47.237,"text":"Здание примечательно само по себе: в народе его прозвали «элеватор» в силу некоторого сходства. Постановки музыкальные: оперы, оперетты, балет, детские музыкальные спектакли. Часто используется как площадка для финалов конкурсов красоты и прочих событий культурной жизни города.","title":"Чебоксары","revision":775884,"license":"CC BY-SA 4.0","image":"TOB-2017.jpg"},"ru-bb035cc31dc2-o294bed9c6fb6":{"name":"Бункер Сталина","kind":"museum","lat":53.1966433,"lon":50.0978279,"text":"Бункер, в котором Сталин никогда не был, почему-то невероятно популярен среди туристов. Находится под жилым домом по улице Фрунзе, попасть внутрь можно только с групповой экскурсией. Заказывайте экскурсию заранее.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":"Stalin's Bunker 0009.JPG"},"ru-bb035cc31dc2-o647f87c6ec3b":{"name":"Самарский зоопарк","kind":"family","lat":53.222639,"lon":50.163203,"text":"Обычный провинциальный старый зоопарк с неплохой коллекцией фауны, включая африканских львов и амурских тигров. Со всех сторон окружён густой зелёной зоной.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"ru-bb035cc31dc2-oab71cfc0b90a":{"name":"Театр «Самарская площадь»","kind":"theater","lat":53.19868,"lon":50.1132,"text":"Экспериментальный театр-студия, созданный местным режиссёром Евгением Дробышевым.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"ru-bb035cc31dc2-oabfab43520c3":{"name":"Самарская филармония","kind":"live","lat":53.1917,"lon":50.0949,"text":"Отличная филармония: интересные концерты, недорогие билеты; есть орган. Здание филармонии — прекрасный памятник модерна, хотя и ненастоящего. Оно построено в 1980-е годы на месте бывшего «Цирка Олимп», где пел ещё Фёдор Шаляпин.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":"Самарская филармония( Театр Олимп).jpg"},"ru-bb035cc31dc2-o7f8043fab466":{"name":"Театр «Место действия»","kind":"theater","lat":53.1902,"lon":50.1185,"text":"Камерный драматический театр с молодыми актёрами. В репертуаре пьесы классиков и современных драматургов. Также проходят выставки, видеопоказы, образовательные лектории, экспериментальные формы театрального действия.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"ru-bb035cc31dc2-o3e9db2438980":{"name":"Samara gastro","kind":"food","lat":53.2131,"lon":50.1248,"text":"Формат «гастро-маркет», он же фуд-корт, то есть несколько разных кафе в одном здании. Разные кухни, разные цены. Есть столики с видом на Волгу. В пятницу и субботу работают допоздна. Платная парковка.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"ru-bb035cc31dc2-o3416d517788e":{"name":"Кофейня White Cup","kind":"coffee","lat":53.19411,"lon":50.0967,"text":"Двор между костёлом и музеем модерна — сердце старой Самары, где красота, что называется, не знает границ. Кофейня под стать своему окружению: её оформлением занимался профессиональный архитектор Дмитрий Храмов, придумавший развесить под потолком кружки с изображениями памятников самарского модерна, превратив их в карту достопримечательностей.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"ru-bb035cc31dc2-ofc74f4c4ea3e":{"name":"Рюмочная «Боря»","kind":"night","lat":53.18902,"lon":50.09807,"text":"Советская рюмочная на хипстерский манер: закуски-бутерброды подают на стильных деревянных дощечках, хотя и с классическим содержимым вроде селёдки или докторской колбасы. Ассортимент разнообразный — от Жигулёвского пива и недорогой водки до импортных дистиллятов и фирменных настоек собственного приготовления.","title":"Самара","revision":773041,"license":"CC BY-SA 4.0","image":null},"spb-o6b351868482f":{"name":"Кунсткамера","kind":"museum","lat":59.941667,"lon":30.304444,"text":"Первый российский музей, учрежденный Петром I на основе его личной коллекции. В переводе с немецкого означает «кабинет редкостей». Здание Кунсткамеры по проекту Маттарнови строилось в 1718—1734 годах. В башне была устроена обсерватория и установлен сохранившийся до наших дней Готторпский глобус, по сути являющийся планетарием.","title":"Санкт-Петербург/Васильевский остров","revision":641703,"license":"CC BY-SA 4.0","image":null},"spb-ob79fe80dfe75":{"name":"Приморский парк Победы","kind":"park","lat":59.9718,"lon":30.2419,"text":"На территории работает парк аттракционов «Диво Остров», несколько ресторанов и кафе, на главном входе в парк - пункт проката велосипедов и роликов.","title":"Санкт-Петербург/Петроградская сторона","revision":690626,"license":"CC BY-SA 4.0","image":"Приморский парк Победы. Второй северный пруд.JPG"},"spb-oa00de1586a3d":{"name":"Каменноостровский театр","kind":"theater","lat":59.976404,"lon":30.274673,"text":"Единственный сохранившийся в Санкт-Петербурге памятник деревянного зодчества эпохи классицизма. Здание было построено в 1827 г. по проекту архитектора С. Л. Шустова. Значительно реконструирован в 2007—2010 годах для современного использования.","title":"Санкт-Петербург/Петроградская сторона","revision":690626,"license":"CC BY-SA 4.0","image":"Kamennoostrovsky Theatre 1.jpg"},"spb-o1c48a5839691":{"name":"Театр «Мюзик-Холл»","kind":"theater","lat":59.955162,"lon":30.310421,"text":"Открыт с 1928 года. Размещается в здании народной аудитории Народного дома, построенной по инициативе принца А. П. Ольденбургского архитектором Высочайшего двора Г. И. Люцедарским в 1910—1912 годах.","title":"Санкт-Петербург/Петроградская сторона","revision":690626,"license":"CC BY-SA 4.0","image":"Music hall theater in SPB.jpg"},"spb-oca5bf425fe5a":{"name":"Особняк Глуховского","kind":"food","lat":59.965773,"lon":30.280668,"text":"Ресторан с ценами выше среднего в историческом доме с мезонином постройки начала XIX в. Каждый этаж оформлен в своем стиле, имеются в наличии — Английский клуб, Генеральский салон, Альпийская дача.","title":"Санкт-Петербург/Петроградская сторона","revision":690626,"license":"CC BY-SA 4.0","image":null},"spb-o3bacc6aee1f1":{"name":"Нарвские триумфальные ворота","kind":"museum","lat":59.900842,"lon":30.273823,"text":"Ворота установлены в 1834г в память героев Отечественной войны 1812 года по проекту Стасова. Представляют собой арку высотой 30 метров, украшенную фигурами воинов и колесницей Славы. В верхней части Нарвских ворот находится небольшой музей, посвященный войне 1812г и истории создания памятника.","title":"Санкт-Петербург/Юго-запад","revision":594518,"license":"CC BY-SA 4.0","image":"Narva Triumphal Arch.jpg"},"spb-of39c3063686b":{"name":"Здание Главного штаба","kind":"architecture","lat":59.938166,"lon":30.317264,"text":"Великий шедевр архитектора Росси построен в 1819 — 1829 годах и сформировал Дворцовую площадь как единый ансамбль. Состоит из двух корпусов, образующих гигантскую 580-метровую дугу. Корпуса соединены триумфальной аркой, посвященной победе в Отечественной войне 1812 года.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Hermitage from inside.jpg"},"spb-oe5ec2615a7d3":{"name":"Летний сад","kind":"park","lat":59.944722,"lon":30.335556,"text":"Идея создания в Петербурге паркового ансамбля восходит ещё к Петру I. Строительство Летнего сада началось уже в 1704 году, всего через год после закладки Петропавловской крепости.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Летний сад (2).jpg"},"spb-obe035100bf5b":{"name":"Исаакиевский собор","kind":"architecture","lat":59.934156,"lon":30.305936,"text":"Главный храм города, одна из высотных доминант исторического центра. Изначальная церковь св. Исаакия построена недалеко от Адмиралтейства в 1710 г. День рождения Петра I приходится на день памяти этого святого, именно поэтому самый большой собор города, основанного Петром, носит имя малоизвестного святого.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Saint Isaac's Cathedral in SPB.jpeg"},"spb-oc5c3d3b6a855":{"name":"Памятник Николаю I","kind":"architecture","lat":59.932178,"lon":30.308441,"text":"Конный памятник императору Николаю I, установленный в центре Исаакиевской площади в 1859 году. Общая концепция памятника была разработана Огюстом Монферраном. Модель по рисункам Монферрана выполнил Роберт Залеман. Конную статую отлил Пётр Клодт, создатель знаменитых «Укротителей» на Аничковом мосту.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Nicholas I Monument.jpg"},"spb-oc4161a19c189":{"name":"Мариинский дворец","kind":"museum","lat":59.930866,"lon":30.309604,"text":"Дворец, построенный в 1839—1844 годах архитектором Андреем Штакеншнейдером для дочери Николая I великой княжны Марии Николаевны, по имени которой и получил название. Фасад имеет три ризалита. Второй и третьи этажи дворца украшены колоннами и пилястрами коринфского ордера.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"St Petersburg, Mariinskiy Palace.jpg"},"spb-o2139473a2f24":{"name":"Памятник Екатерине II","kind":"architecture","lat":59.933363,"lon":30.336991,"text":"Находится в сквере между зданиями Российской национальной библиотеки и Аничкова дворца. Общий замысел принадлежит известному скульптору Михаилу Микешину. Скульптура Екатерины II отлита по модели Матвея Чижова.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Denkmal für Katharina II. in St. Petersburg.jpg"},"spb-oda2e0a89dc82":{"name":"Дворец Белосельских-Белозерских","kind":"architecture","lat":59.932831,"lon":30.343948,"text":"Сооружён в 1849 году по проекту архитектора А. И. Штакеншнейдера в стиле так называемого «второго барокко».","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":"Sankt-Petěrburg 035.jpg"},"spb-o927b89825cc1":{"name":"Кинотеатр Аврора","kind":"family","lat":59.934332,"lon":30.339267,"text":"Кинотеатр с историей, открылся под названием «Пикадилли» в 1913г. Несмотря на реконструкции, историческая атмосфера в архитектуре и интерьерах сохранилась. Два зала, помимо стандартного репертуара, показывают старую классику и фильмы ограниченного проката. Даже если не хочется в кино, стоит свернуть с Невского во двор и осмотреть здание и фойе внутри.","title":"Санкт-Петербург/Центр","revision":779676,"license":"CC BY-SA 4.0","image":null},"ru-1ccfdc3cbe0f-ocd456aaecb38":{"name":"Мордовское подворье","kind":"food","lat":54.178291,"lon":45.17739,"text":"Единственный в городе ресторан, специализирующийся на мордовской кухне. Меню весьма обширное. Горячее стоит в районе 600-1200 р.","title":"Саранск","revision":782836,"license":"CC BY-SA 4.0","image":null},"ru-bf465fda7834-od56a50396ab3":{"name":"Набережная Космонавтов","kind":"architecture","lat":51.5247925,"lon":46.0473704,"text":"Длинная набережная между Речным вокзалом и Ротондой, несколько ярусов пешеходных дорожек: верхние — среди деревьев и газонов, а по нижнему ярусу, около воды можно кататься на велосипедах и самокатах. На набережной установлен не очень удачный памятник Юрию Гагарину.","title":"Саратов","revision":780772,"license":"CC BY-SA 4.0","image":"Саратов набережная 4.jpg"},"ru-bf465fda7834-ob9d7d029636c":{"name":"Памятник Чернышевскому","kind":"architecture","lat":51.52979,"lon":46.03525,"text":"Установлен на том месте, где до 1917 года стоял памятник императору Александру II.","title":"Саратов","revision":780772,"license":"CC BY-SA 4.0","image":"Памятник Чернышевскому у парка Липки.jpg"},"ru-efc02a6a273b-o21ae0c6ef188":{"name":"Le buffet","kind":"coffee","lat":54.917373815204854,"lon":37.4257488741703,"text":"Кафе самообслуживания в большом торговом центре. Еда неплохая, к ней прилагается неплохой вид из окна на город.","title":"Серпухов","revision":749138,"license":"CC BY-SA 4.0","image":null},"ru-7fa968734865-ob8897504795e":{"name":"Кафе «Релакс»","kind":"coffee","lat":61.70415,"lon":30.69281,"text":"Какие бы мысли ни навевало название заведения, это всё же классический ресторан, где быстро и вкусно готовят; особенно хороши супы на сырной основе. Никаких эксклюзивных блюд нет, но меню внушительных размеров. Приятная обстановка. Заведение некогда было лучшим в городе, хотя с увеличением конкуренции перешло в разряд средних.","title":"Сортавала","revision":757415,"license":"CC BY-SA 4.0","image":null},"ru-2a1c7bdb05ea-o08efcaed7f6d":{"name":"Тифлисские ворота","kind":"architecture","lat":45.0521,"lon":41.9928,"text":"Ещё один фрагмент губернского Ставрополя — триумфальная арка, первоначально возведённая в 1841 году к 30-летию Бородинской битвы. Тогда ворота располагались в конце Николаевского тракта, ныне проспекта Карла Маркса. В советское время их разрушили, а в конце 1990-х построили заново и немного переместили.","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":"GOPR5087.JPG"},"ru-2a1c7bdb05ea-o9db4b76cbe58":{"name":"Ставропольская краевая филармония","kind":"live","lat":45.04993,"lon":41.9843,"text":"Изначально филармония и соседний с ней магазин «Пассаж» были одним зданием 1912 года постройки. До революции он принадлежал братьям Меснянкиным, в нём располагались театр, кинотеатр «Модернъ», торговые галереи и рестораны.","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":"Здание театра братьев меснянкиных.JPG"},"ru-2a1c7bdb05ea-o61f0c3bee2d5":{"name":"Ресторан «Каштан»","kind":"food","lat":45.04692,"lon":41.97495,"text":"Расположен на бульваре Ермолова в центре города. Ранее на этом месте располагалось кафе «Снежинка», прозванное в народе «сугроб».","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":null},"ru-2a1c7bdb05ea-o92c29a76a1ca":{"name":"Чайхана «Бархан»","kind":"food","lat":45.01636,"lon":41.93115,"text":"Ресторан узбекской кухни, довольно богато обставленный. Есть кальян и караоке.","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":null},"ru-2a1c7bdb05ea-oc337bc356a63":{"name":"Diner's","kind":"coffee","lat":45.03823,"lon":41.96357,"text":"Кафе, оформленное в стиле американского дайнера 50-х. Кухня эклектична и характерна для многих подобных заведений: тут вам и бургеры, и мини-пиццы, и суши. Подают довольно вкусный том-ям.","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":null},"ru-2a1c7bdb05ea-ob27e878c5277":{"name":"Шеф Пушкин","kind":"food","lat":45.03932,"lon":41.963,"text":"Интересная обстановка с низкими потолками, изразцовой печью. Вежливый персонал. Блюда русской, кавказской и европейской кухни.","title":"Ставрополь","revision":699082,"license":"CC BY-SA 4.0","image":null},"ru-ea2a12701e19-o1391b7708f7a":{"name":"«Наместник»","kind":"food","lat":52.73528,"lon":41.45093,"text":"Подходящее место для банкетов и корпоративов; удобно поужинать, если вы поселились в гостинице «Державинская».","title":"Тамбов","revision":755453,"license":"CC BY-SA 4.0","image":null},"ru-c52ea942555e-o867234055c86":{"name":"Абракнигабра","kind":"books","lat":56.854309,"lon":35.91012,"text":"Книжный магазин, настолько большой, что обладает даже собственным кафе.","title":"Тверь","revision":699181,"license":"CC BY-SA 4.0","image":null},"ru-c52ea942555e-o0174f18727eb":{"name":"Чикен хауз","kind":"food","lat":56.855631,"lon":35.910042,"text":"Тверь может похвастать собственной сетью фаст-фуда. Отличительная черта этих заведений — круглосуточная работа, но, за исключением одного кафе на Трехсвятской, находятся они вне центра. Кроме бургеров и картошки в меню есть и супы с салатами. Как и обычно в фастфуде, днем бывает очень людно и шумно.","title":"Тверь","revision":699181,"license":"CC BY-SA 4.0","image":null},"ru-c52ea942555e-o0822d5b68a58":{"name":"Кафе «Манилов»","kind":"coffee","lat":56.859418,"lon":35.9152035,"text":"Недорогое кафе с обстановкой в стиле дореволюционной квартиры. По будням бизнес-ланчи от 160 до 270 ₽. Обслуживание небыстрое.","title":"Тверь","revision":699181,"license":"CC BY-SA 4.0","image":null},"ru-c52ea942555e-o517657e062be":{"name":"Фабрика блюза","kind":"coffee","lat":56.8599918,"lon":35.903787,"text":"Недорогой пивной бар, очень хорошие отзывы. Несмотря на название, интерьер тяготеет, скорее, к металу, и музыка играет соответствующая","title":"Тверь","revision":699181,"license":"CC BY-SA 4.0","image":null},"ru-e3b0eae8a4ce-o7663a04af6da":{"name":"Goodwin cinema","kind":"family","lat":56.4888,"lon":84.97816,"text":"Находится в ТРЦ \"Изумрудный город\". Многозальный, в том числе 3D, 5D, Action Hall, INvision.","title":"Томск","revision":708219,"license":"CC BY-SA 4.0","image":null},"ru-4b7047b6a656-o8755ae208128":{"name":"Спасо-Преображенский собор","kind":"architecture","lat":57.03879,"lon":34.95837,"text":"Символ города — огромный собор в стиле ампир, построенный в 1812-1822 гг. предположительно по проекту Карла Росси силами его ученика Ивана Мокшеева. Деревянная церковь стояла на этом месте с момента основания Новоторжского кремля; она сгорела в 1238 году при монгольском нашествии и была в 1364 году отстроена в камне.","title":"Торжок","revision":750239,"license":"CC BY-SA 4.0","image":"Spaso-Preobrazhenskiy Cathedral (Torzhok).jpg"},"ru-4b7047b6a656-odc4fad967c04":{"name":"Монастырская трапезная","kind":"coffee","lat":57.032562,"lon":34.956304,"text":"Хороший вариант быстрого и дешёвого обеда, если вы гуляете вокруг Борисоглебского монастыря. К тому же трапезная находится в историческом здании, так что можно заодно осмотреть его изнутри. Принимают только наличные.","title":"Торжок","revision":750239,"license":"CC BY-SA 4.0","image":"Торжок. Улица Старицкая 9А (Монастырская трапезная).jpg"},"ru-b2601b186da2-o42670968fdb5":{"name":"Тульский академический театр драмы","kind":"theater","lat":54.18861,"lon":37.61028,"text":"Ведёт свою историю с 1777 года, уже через 11 лет его посетила императрица Екатерина II. Здесь выступал актёр М.С. Щепкин, ставились произведения Л.Н. Толстого с личным присутствием автора. Располагается в просторном здании 1970 года с классическими интерьерами и со скульптурной композицией «Музы» на фасаде, рядом в 2008 году был открыт сквер с фонтанами.","title":"Тула","revision":729131,"license":"CC BY-SA 4.0","image":"Тула. Драматический театр.jpg"},"ru-b2601b186da2-o600d3f3e6a49":{"name":"Тульская областная филармония","kind":"live","lat":54.1857,"lon":37.6098,"text":"Здание филармонии, построенное в начале XX века, сочетает стили неоклассицизма и модерна, было открыто в 1912 году как Дворянский клуб, после революции там размещался драматический театр. Филармония, появившаяся в Туле в 1937 году, переехала в современное здание уже в 1970-х годах, вторая её сцена находится в доме Дворянского собрания.","title":"Тула","revision":729131,"license":"CC BY-SA 4.0","image":"Тула. Областная Филармония.jpg"},"ru-b2601b186da2-o89e976742195":{"name":"Ресторан «Метрополь»","kind":"coffee","lat":54.18645,"lon":37.60931,"text":"Меню относительно небольшое, ориентирован на проведение банкетов. С 12 до 16 ч бизнес-ланч.","title":"Тула","revision":729131,"license":"CC BY-SA 4.0","image":null},"ru-b2601b186da2-o5388dcedddfd":{"name":"Ресторан-пивоварня «Пётр Петрович»","kind":"food","lat":54.18469,"lon":37.593464,"text":"Назван в честь доктора Белоусова, по инициативе которого в 1893 году был разбит парк, на территории которого и находится заведение. На втором этаже балкон с красивым видом на аллеи парка. Всего 3 этажа, часть первого занимает пивоварня, в которой варят тёмное, светлое, венское и пшеничное пиво, в наличии есть и крафтовые сорта.","title":"Тула","revision":729131,"license":"CC BY-SA 4.0","image":null},"ru-b2601b186da2-o54853d793430":{"name":"Ресторан PUBLIC","kind":"food","lat":54.192347,"lon":37.599449,"text":"Восточно-европейская кухня и приятная атмосфера. В «Public» хороший выбор блюд, в том числе традиционных сербских и чешских, порции средние. На открытой кухне готовят гуляш-суп в хлебе, плескавицу, караджорджев шницель, долму, ризотто, стейк из тунца. На открытой веранде можно укрыться пледом. Бар, бесплатный Wi-Fi.","title":"Тула","revision":729131,"license":"CC BY-SA 4.0","image":null},"ru-7339e8342cb4-oed15f09cf094":{"name":"Дом башкирской кухни","kind":"food","lat":54.7347,"lon":55.9555,"text":"Крупнейшее из заведений сети «Пышка» представляет собой большую столовую с умеренным влиянием башкирской кулинарии и обилием таких «традиционных» блюд как сосиска в тесте или окрошка. Идеальное место для того, чтобы поесть дёшево и быстро.","title":"Уфа","revision":761761,"license":"CC BY-SA 4.0","image":null},"ru-7339e8342cb4-o8789b16c9331":{"name":"Чайхана «Дуслык»","kind":"food","lat":54.72736,"lon":55.95041,"text":"Ресторан восточной и башкирской кухни. Можно попробовать суп элеш, бешбармак, плов по-башкирски и, конечно же, национальную выпечку. Немало турецко-азербайджанских блюд.","title":"Уфа","revision":761761,"license":"CC BY-SA 4.0","image":null},"ru-884c84a20141-oc801bd444cab":{"name":"«Муус Хайа»","kind":"food","lat":62.02443,"lon":129.7101,"text":"Ресторан в районе университета, основной зал с дорожками для боулинга. Оформлен фотографиями с видами Якутии (автор — собственник ресторана — известный в республике путешественник и альпинист Егор Макаров). Четыре малых зала (один из них со старинной утварью), где можно собраться большой и малой компанией. Есть бизнес-ланч.","title":"Якутск","revision":776552,"license":"CC BY-SA 4.0","image":null},"ru-6b1bab7dee45-od17338593841":{"name":"Ресторан «Мили»","kind":"food","lat":57.631225,"lon":39.841358,"text":"Называют себя концептуальным рестораном авторской кухни. Разнообразное меню, интересная подача. Особенно хороши десерты.","title":"Ярославль","revision":777682,"license":"CC BY-SA 4.0","image":null},"ru-a4859da89977-ob4eb9eeb0c05":{"name":"Дальневосточный художественный музей","kind":"museum","lat":48.473201,"lon":135.052441,"text":"Искусство античного мира, стран Западной Европы и народов Востока, русское дореволюционное и советское искусство, а также искусство коренных народов Крайнего Севера и Дальнего Востока.","title":"Хабаровск","revision":758561,"license":"CC BY-SA 4.0","image":"Хабаровск, краевая филармония и художественный музей фото1.JPG"},"ru-79da737a603b-o367e2e7249f5":{"name":"Летний театр","kind":"theater","lat":43.568805,"lon":39.733295,"text":"Обычно летний театр — это наспех сбитая из досок сцена под открытым небом, но в Сочи всё по-другому. Летний театр был построен в 1937 году вслед за зимним в том же классическом стиле — с портиками, хотя и без крыши. Пожалуй, нигде больше в России летние театры не строили столь основательно.","title":"Хостинский район","revision":385242,"license":"CC BY-SA 4.0","image":"Letniy theatre Sochi.jpg"},"ru-79da737a603b-off364ecfbf52":{"name":"Сад-музей «Дерево дружбы»","kind":"museum","lat":43.567072,"lon":39.747515,"text":"«Дерево дружбы» представляет собой целый цитрусовый сад под одной кроной и от одного корня. Здесь привиты японские мандарины, итальянские лимоны, американские грейпфруты, испанские апельсины.","title":"Хостинский район","revision":385242,"license":"CC BY-SA 4.0","image":"Friendship Tree Garden Museum 15.JPG"},"ru-79da737a603b-o9352a7a3458f":{"name":"Санаторий «Металлург»","kind":"park","lat":43.56332,"lon":39.76015,"text":"Замыкает триаду санаториев по чётной стороне Курортного проспекта. «Металлург» построен в 1953-56 гг. в самых что ни на есть классических формах: огромное полукруглое здание из тёмного камня украшено портиком и в некоторых ракурсах кажется античным храмом.","title":"Хостинский район","revision":385242,"license":"CC BY-SA 4.0","image":null},"ru-b22cf685e391-o12226a9ce78d":{"name":"Ледовый дворец «Витязь»","kind":"active","lat":55.42021,"lon":37.51616,"text":"Центральный спортивный объект города, домашняя арена ныне не существующего хоккейного клуба «Витязь», выступавшего в КХЛ. На арене проводятся массовые катания, как правило, в вечернее время суток. У входа в здание в 2000 году установили скульптуру русского витязя на коне.","title":"Подольск","revision":776594,"license":"CC BY-SA 4.0","image":"ЛД Витязь (Подольск).jpg"},"ru-b22cf685e391-o577736594ac8":{"name":"«Додо Пицца»","kind":"food","lat":55.429183,"lon":37.552441,"text":"Сетевая пиццерия в центре города. Расположена в исторической постройке 1920-х годов – проходной не существующего с 1960-х годов стадиона «Торпедо»","title":"Подольск","revision":776594,"license":"CC BY-SA 4.0","image":"Проходные стадиона Торпедо Подольск.jpg"},"ru-b22cf685e391-o34e40dec865b":{"name":"Ресторан «Отдых»","kind":"food","lat":55.434124,"lon":37.514257,"text":"Одно из немногих заведений общепита в районе подольских усадеб, причём не мутная столовая-распивочная, а полноценный ресторан с аккуратным интерьером. Меню, впрочем, совершенно стандартное.","title":"Подольск","revision":776594,"license":"CC BY-SA 4.0","image":null},"ru-eeb7a0a73bbf-o06fa0484c57c":{"name":"Brookwin","kind":"food","lat":44.895454,"lon":37.306727,"text":"Заведение позиционирует себя как гастробар. Большой выбор качественных вин из хозяйств Таманского полуострова и прилегающих районов. Выбор еды невелик, но включает местные специалитеты. Цены выше, чем в среднем по городу.","title":"Анапа","revision":623539,"license":"CC BY-SA 4.0","image":null},"ru-e69a280f9064-o0b529b7b3554":{"name":"Дача Башенина","kind":"museum","lat":56.4745,"lon":53.7923,"text":"Выдающийся особняк в стиле модерн был построен в 1909 году для городского головы купца Башенина. Автором проекта считают всё того же Чарушина, хотя на этот счёт имеются разночтения, как есть они и относительно материала для строительства: снаружи особняк выглядит деревянным, напоминая старые дачи где-нибудь в окрестностях Петербурга, однако каркас вроде бы…","title":"Сарапул","revision":623329,"license":"CC BY-SA 4.0","image":"Дача купца Башенина.JPG"},"ru-9bacca6d4ed5-oa3042d9a8a1e":{"name":"Кафе «Пицца»","kind":"coffee","lat":52.88875,"lon":40.50994,"text":"Лидер по неоригинальности своего названия и в то же время неплохое кафе с обслуживанием и полным меню, а совсем не одной только пиццей.","title":"Мичуринск","revision":602402,"license":"CC BY-SA 4.0","image":null},"ru-fc14353f5a1d-obd9ab3cc59ab":{"name":"Салаватский государственный башкирский драматический театр","kind":"theater","lat":53.352047,"lon":55.943548,"text":"Салаватский государственный башкирский драматический театр создан на базе колхозно-совхозного театра, работающего с 1933 года. В театре ставятся пьесы классиков башкирской и татарской драматургии на башкирском языке с синхронным переводом на русский. В 1970-х гг. годах театру передали первый этаж здания на площади Победы.","title":"Салават","revision":466287,"license":"CC BY-SA 4.0","image":null},"kzn-o0d23abd2e2b2":{"name":"Кафе Govinda's","kind":"food","lat":55.82209,"lon":49.15372,"text":"Самое вегетарианское кафе Казани, Govinda's работает под лозунгом «вегетарианцы — тоже люди» и предлагает обычную русскую и татарскую еду, но в вегетарианском исполнении: салат оливье, плов, шашлык, манты, борщ, треугольники (эчпочмак) и даже чебуреки, причём всё это без мяса. А десерты здесь почему-то индийские.","title":"Казань/Заречье","revision":698514,"license":"CC BY-SA 4.0","image":null},"kzn-o2a4e1bb9f230":{"name":"Coffee Bean","kind":"coffee","lat":55.82758,"lon":49.13749,"text":"Многие жители Казани убеждены, что лучший в городе кофе подают именно здесь. Трудно судить, правда это или нет — ведь Coffee Bean не более чем сетевая кофейня, на которую в Москве никто бы и внимания не обратил. К плюсам заведения можно отнести его истинно кофейный характер: здесь нет ни салатов, ни горячей еды, зато выбор десертов и кофе впечатляет.","title":"Казань/Заречье","revision":698514,"license":"CC BY-SA 4.0","image":null},"kzn-o77b180a156fb":{"name":"Ресторан «Катык»","kind":"food","lat":55.82855,"lon":49.13282,"text":"Возможно, вы видели в Казани магазины сети Катык, торгующие полуфабрикатами и выпечкой. К той же сети относится ресторан, являющийся, пожалуй, самым окраинным рестораном татарской кухни. Знаменит он тем, что татарскую еду подают официанты в белых перчатках в залах с безвкусными интерьерами под живую музыку из серии «дискотека 80-х».","title":"Казань/Заречье","revision":698514,"license":"CC BY-SA 4.0","image":null},"kzn-of6d8aa712ef0":{"name":"Кафе «Сады»","kind":"coffee","lat":55.77016,"lon":49.17566,"text":"Тут полный халяль, то есть не только правильная еда, но и официантки в платках, и даже специальная молельная комната. А ещё почему-то зал, оформленный в деревянном стиле и очень напоминающий баню. Отзывы неизменно хорошие.","title":"Казань/Проспект Победы","revision":385022,"license":"CC BY-SA 4.0","image":null},"kzn-o150be83b0e50":{"name":"Центральный рынок","kind":"market","lat":55.78629,"lon":49.1085,"text":"Огромный рынок, раскинувшийся между Московской улицей и железной дорогой, до сих пор известен в народе как Колхозный, хотя местами он напоминает настоящий восточный базар. Здесь мясные ряды и торговля лесными ягодами чередуются с магазином золотых украшений и кафе узбекской кухни. Колоритно, но вряд ли вы найдёте что-то особенное.","title":"Казань/Татарская слобода","revision":766069,"license":"CC BY-SA 4.0","image":null},"kzn-o099a93ed9241":{"name":"Ресторан «Приют холостяка»","kind":"food","lat":55.7906,"lon":49.10742,"text":"Приют холостяка — это не грязная закусочная и не шумная рюмочная, а авторский ресторан, стиль которого определить невозможно, но нельзя не признать, что оформлен он со вкусом.","title":"Казань/Татарская слобода","revision":766069,"license":"CC BY-SA 4.0","image":null},"kzn-oa5d107779670":{"name":"Благовещенский собор","kind":"architecture","lat":55.7999,"lon":49.1063,"text":"Памятник русской архитектуры XVI века. Собор предположительно возведен в 1562 псковским архитектором Постником Яковлевым, создателем собора Василия Блаженного в Москве. Каменный собор был сооружён на месте деревянной церкви, заложенной Иваном Грозным и построенной за три дня в октябре 1552 года, после взятия города.","title":"Казань/Кремль и Русская слобода","revision":767049,"license":"CC BY-SA 4.0","image":"Благовещенский собор - panoramio (2).jpg"},"kzn-oad5d9bee1c9e":{"name":"Добрая столовая","kind":"food","lat":55.79086,"lon":49.11503,"text":"Эта столовая не имеет себе равных по дешевизне — ни на улице Баумана, ни в Казани вообще.","title":"Казань/Кремль и Русская слобода","revision":767049,"license":"CC BY-SA 4.0","image":null},"kzn-o764e7f80c88e":{"name":"Дом татарской кулинарии","kind":"food","lat":55.78987,"lon":49.11717,"text":"Справа от входа есть летняя веранда, где продается на вынос выпечка из пекарни ресторана. Можно попробовать вегетарианский вариант плова.","title":"Казань/Кремль и Русская слобода","revision":767049,"license":"CC BY-SA 4.0","image":null},"msk-oa1ee1e3f0dcf":{"name":"Храм Святителя Николая в Сабурове","kind":"architecture","lat":55.6397,"lon":37.70015,"text":"Православный храм, объект культурного наследия Российской Федерации. Построен в конце XVI века, затем разобран в 1861 году, через 4 года вновь выстроен и восстановлен в 90-ые годы 20 века.","title":"Москва/Юг","revision":756361,"license":"CC BY-SA 4.0","image":"Nicholas Church Moscow Saburovo.jpg"},"ru-79da737a603b-o77ffacdb7041":{"name":"«Red Cafe»","kind":"coffee","lat":43.5963,"lon":39.72137,"text":"Уютное кафе на все случаи жизни, но посетители особенно рекомендуют кофе, хотя похоже, что выбор алкогольных напитков здесь тоже более чем достойный.","title":"Центр Сочи","revision":758403,"license":"CC BY-SA 4.0","image":null},"ru-6d7c3e9e8d6d-o21ee23e8dd1c":{"name":"Трактир «Ильинский»","kind":"food","lat":58.2047,"lon":68.2585,"text":"Кафе русской кухни в реконструированном деревянном особняке. Меню выглядит привлекательно, однако посетители жалуются на медленное обслуживание и посредственные вкусовые качества самих блюд. Вечером может быть караоке.","title":"Тобольск","revision":735076,"license":"CC BY-SA 4.0","image":"Remezova20 Tobolsk.JPG"},"ru-05a647ffb859-o6790e63523d0":{"name":"Морозовская дача","kind":"architecture","lat":55.0919,"lon":36.58603,"text":"Дом, в котором жили и работали художники Поленов Василий Дмитриевич и Серов Валентин Александрович и в период строительства атомной электростанции Курчатов Игорь Васильевич В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Калужская область/Обнинск","revision":753796,"license":"CC BY-SA 4.0","image":"Усадьба Обнинских «Турлики» («Морозовская дача») iii.jpg"},"ru-79da737a603b-o4a0e6992b42f":{"name":"Аквапарк «Морская звезда»","kind":"family","lat":43.918214,"lon":39.318372,"text":"Аквапарк расположен на открытом воздухе. Имеются два бассейна, 11 горок, плюс детский бассейн с горками. При аквапарке кафе и ресторан. Посетители сравнивают два аквапарка в Лазаревском, и вывод состоит в том, что различий в качестве нет, но «Морская звезда» больше подходит для любителей активного отдыха, а «Наутилус» поспокойнее.","title":"Лазаревское","revision":677371,"license":"CC BY-SA 4.0","image":null},"ru-79da737a603b-o7d6379306d77":{"name":"Аквапарк АкваЛоо","kind":"family","lat":43.676672,"lon":39.603349,"text":"Крупнейший аквапарк Сочи. Работает круглогодично. Имеется дайвинг-центр с возможностью обучения.","title":"Лоо","revision":396591,"license":"CC BY-SA 4.0","image":null},"ekb-od97e295e5468":{"name":"Доходный дом купца Чувильдина","kind":"architecture","lat":56.83213,"lon":60.60772,"text":"Автор объекта: арх. А.С. Чирковский.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Свердловская область/Екатеринбург (центр - часть 1)","revision":782957,"license":"CC BY-SA 4.0","image":"Доходный дом Чувильдина (Екатеринбург Горького) 1.JPG"},"msk-oaa290c9f0cc0":{"name":"Большой Кремлёвский дворец","kind":"architecture","lat":55.749863,"lon":37.61591,"text":"В ансамбль Большого Кремлёвского дворца, расположенного на южной линии Кремлёвского холма, входит новый дворец XIX века и несколько более древних зданий XV-XVII веков. Новый парадный дворец со смотрящим на Кремлёвскую набережную главным фасадом был построен в 1838—1849 годах под руководством Константина Тона.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"Moscow Grand Kremlin Palace4.jpg"},"msk-oefce17ef2a66":{"name":"Сенатский дворец","kind":"architecture","lat":55.753298,"lon":37.619273,"text":"Дворец построен в 1776-1787 годах по проекту Матвея Казакова в стиле классицизма. Название связано с тем, что дворец изначально строился для двух департаментов Правительствующего сената, которые как раз перед этим были переведены из Петербурга в Москву. Впоследствии во дворце что только не размещалось — например, Московское архитектурное училище.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"MoscowKremlin Senate.jpg"},"msk-o91103be050d5":{"name":"Тайницкий сад","kind":"park","lat":55.75033,"lon":37.61951,"text":"Расположен вдоль южной стены Кремля, рядом с Тайницкой башней, откуда и название. В 2013 году в парке была построена (без согласования с ЮНЕСКО) вертолётная площадка.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"MoscowKremlin TainitskyiGarden 1134.JPG"},"msk-oe1ff5191e2db":{"name":"Воскресенские ворота","kind":"architecture","lat":55.755556,"lon":37.618056,"text":"Двойные (две башни, каждая с аркой) проездные ворота расположены между зданиями Городской думы и Исторического музея. Изначально построены в 1535 году, в 1931 году снесены для того, чтобы обеспечить проход тяжёлой технике во время парадов. В 1994—1995 гг. ворота, а также пристроенная к ним Иверская часовня (1791, снесена в 1929) были восстановлены.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"MoscowKremlin ResurrectionGate S82.jpg"},"msk-o3dd24282a7ac":{"name":"Дом Пашкова","kind":"architecture","lat":55.74977,"lon":37.60852,"text":"Один из лучших памятников русского классицизма, обычно приписывается Василию Баженову, хотя документальных свидетельств того, что проект принадлежит Баженову, нет. Дом был построен в 1784—1786 годах для офицера Петра Пашкова, а в 1839 году был продан Московскому университету. С 1921 года в здании размещается библиотека.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"Moscow PashkovHouse.JPG"},"msk-od874511ec8a4":{"name":"Государственный Кремлёвский дворец","kind":"theater","lat":55.751397,"lon":37.615588,"text":"Бывший дворец съездов, открывшийся в 1961 году, после 1991 года превратился в крупнейшую концертную площадку страны. Здание в стиле советского модернизма было построено на территории Кремля, на месте старого здания Оружейной палаты начала XIX века.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":"Кремлевский дворец съездов - panoramio.jpg"},"msk-oe46fa89f2aa5":{"name":"Корчма «Тарас Бульба»","kind":"food","lat":55.75064,"lon":37.61017,"text":"Ближайшее ко входу в Кремль место, где можно поесть, причём поесть плотно и со вкусом, в лучших традициях украинской кухни. Стиль можно охарактеризовать как лубок, если, конечно, это понятие вообще применимо к украинской традиции. Официанты в панталонах и вышиванках, на стенах рушники, а где-то в глубине зала стоит русская, она же украинская печь.","title":"Москва/Кремль и Китай-город","revision":733676,"license":"CC BY-SA 4.0","image":null},"ru-40ae04e39a69-o67c5553a9341":{"name":"Московский областной театр драмы и комедии","kind":"theater","lat":55.85484,"lon":38.44009,"text":"Выступали в 1918 г. Крупская Надежда Константиновна, в 1924 г. - Калинин Михаил Иванович, в 1925 г. - Луначарский Анатолий Васильевич. Кинотеатр «Колизей», Ногинский государственный драматический театр, Московский областной театр драмы и комедии (действующий театр) Автор объекта: Василий Иванович Мясников (1914). Архитектурный стиль: модерн.","title":"Культурное наследие России/Московская область/Ногинск","revision":754519,"license":"CC BY-SA 4.0","image":"МОТДИК.jpg"},"msk-o8b2609ff02be":{"name":"Усадьба «Старо-Никольское»","kind":"architecture","lat":55.535707,"lon":37.153871,"text":"Застраивается. Место проведения VI съезда Коммунистической партии Китая летом 1928 г., действует Музей VI съезда КПК. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Новомосковский округ","revision":780426,"license":"CC BY-SA 4.0","image":"Kaluga Wikiexpedition (2016-06-11) 0260.jpg"},"ru-8dea00e39aab-o40db18de216d":{"name":"Центр океанографии и морской биологии \"Дельфиния\"","kind":"family","lat":55.058002,"lon":82.887501,"text":"Дельфинарий, в котором ежедневно, кроме понедельника, проводятся цирковые представления. Океанариум с 28 морскими аквариумами.","title":"Новосибирск/Правый берег","revision":749635,"license":"CC BY-SA 4.0","image":null},"ru-8dea00e39aab-o94f4f19dd6d0":{"name":"La Maison","kind":"food","lat":55.02666,"lon":82.91699,"text":"Ресторан, кафе, кондитерская с недешевыми, но вкусными тортами. Расположен в здании - памятнике архитектуры - доме купца Крюкова, который был построен в начале XX века.","title":"Новосибирск/Правый берег","revision":749635,"license":"CC BY-SA 4.0","image":null},"msk-o406f877ed88e":{"name":"Моховая башня Сумского острога","kind":"architecture","lat":55.673579,"lon":37.677914,"text":"Перенесена в усадьбу «Коломенское» в 1931 г. из с. Сумский Посад Беломорского района Карельской АССР. Включена в предмет охраны ОКН 771721313050056 «Башни Николо-Карельского острога» на карте ИСОГД. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Южный округ","revision":781995,"license":"CC BY-SA 4.0","image":"Mokhovaya Tower of Sumskoy Stockaded Fort from the 1680s relocated to Kolemenskoye in Moscow (02).jpg"},"spb-o724672e73a3d":{"name":"Монумент героическим защитникам Ленинграда","kind":"architecture","lat":59.843112,"lon":30.321901,"text":"Автор объекта: арх-ры В.А. Каменский, С.Б. Сперанский, ск. М.К. Аникушин, 1978 г.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Московский район (часть 1)","revision":783809,"license":"CC BY-SA 4.0","image":"Monument to the Heroic Defenders of Leningrad on Victory Square (Saint Petersburg) aerial2.jpg"},"ru-6b1bab7dee45-oa60692240cc5":{"name":"Звонница с церковью Богоматери Печерской","kind":"architecture","lat":57.62115,"lon":39.889862,"text":"Автор объекта: арх. Паньков П.Я.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Ярославская область/Ярославль (часть 1)","revision":783739,"license":"CC BY-SA 4.0","image":"Yaroslavl Spaso-Preobrazhensky Monastery Zvonnitsa the Church of Our Lady of Pechersk IMG 0839 1725.jpg"},"ru-82551e9e14a4-o8a86127fedb8":{"name":"Каскадная лестница","kind":"park","lat":43.89845,"lon":42.727,"text":"Северо-восточный вход в парк со стороны пр. Дзержинского оформлен в виде каскада фонтанов, спускающихся по известняковым плитам в город.","title":"Кисловодск","revision":760916,"license":"CC BY-SA 4.0","image":null},"ru-82551e9e14a4-oe1966a386557":{"name":"Главные нарзанные ванны","kind":"architecture","lat":43.90227,"lon":42.71643,"text":"Длинное здание купален в восточном стиле с индийскими мотивами и изящным полукруглым крыльцом. Обратите внимание на керамические панно, изготовленные в Абрамцеве.","title":"Кисловодск","revision":760916,"license":"CC BY-SA 4.0","image":null},"ru-e0504cf64d81-o02d9a55e958b":{"name":"Ресторан Башня","kind":"food","lat":55.7682,"lon":37.8577,"text":"Ресторанчик сделан в бывшей силосной башне (постройки 19 века), отсюда и название. К башне сделана пристройка. На улице поставлены открытые деревянные кабинки.","title":"Реутов","revision":519723,"license":"CC BY-SA 4.0","image":null},"ru-bc5ed78884c8-oecb17b6fc40c":{"name":"Мортуарий","kind":"architecture","lat":48.758245,"lon":44.783675,"text":"Не используется. Единственный сохранившийся на территории России В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Волгоградская область/Волжский","revision":775178,"license":"CC BY-SA 4.0","image":"Mortuary in Volzhsky 2026.jpg"},"ru-9ae642299f7b-o86ef3dc33a1b":{"name":"Дом Машарова","kind":"museum","lat":57.157994,"lon":65.526458,"text":"Дом был построен тюменским купцом, городским головой П.И. Подаруевым. В марте 1900 года усадьба перешла в собственность Н.Д. Машарова - владельца тюменского чугунолитейного завода, гласного городской Думы (1907-1915). Н.Д. Машаров значительно перестроил дом. Особняк является наглядным примером влияния классицистических форм на жилую архитектуру Тюмени.","title":"Культурное наследие России/Тюменская область/Тюмень","revision":782757,"license":"CC BY-SA 4.0","image":"Ленина, 24.jpg"},"ru-248fbf020ba3-o686235f49b5d":{"name":"Кофейня","kind":"coffee","lat":56.1072,"lon":69.461,"text":"Единственное в центре города приличное кафе обставлено красивой кованной мебелью. Здесь неплохой выбор тортов и варят кофе, а также кормят обычной горячей едой, хотя последней далеко до кулинарного совершенства. Wi-Fi.","title":"Ишим","revision":573487,"license":"CC BY-SA 4.0","image":null},"ru-f147ed70422e-o300af93dd17a":{"name":"Памятник Александру Невскому","kind":"architecture","lat":56.736399,"lon":38.852612,"text":"Автор объекта: ск. С.М. Орлов, арх. Л.Л. Капица. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Ярославская область/Переславль-Залесский","revision":779428,"license":"CC BY-SA 4.0","image":"Памятник Александру Невскому в Переславле-Залесском на Красной площади.jpg"},"ru-9b0efbd022bb-o918a259b0e39":{"name":"Грот Лермонтова","kind":"architecture","lat":44.04,"lon":43.08721,"text":"Грот Лермонтова находится ниже по склону от Эоловой арфы. Он был вырублен по проекту архитекторов братьев Бернардацци в 1831 году на месте небольшой естественной пещеры, обнаруженной в 1828 году. В гроте были высечены каменные скамьи, к нему была проведена аллея. Именно в этом гроте произошло свидание Печорина с Верой:\"... я подошёл к самому гроту.","title":"Пятигорск","revision":763172,"license":"CC BY-SA 4.0","image":null},"ru-a52b73890cfe-o3cd1ac68f27b":{"name":"Зал Воинской Славы","kind":"museum","lat":48.74237,"lon":44.53907,"text":"Здание цилиндрической формы. В центре — скульптура в виде руки погибшего героя с факелом Вечного огня. На стенах – 34 мозаичных знамени с именами погибших защитников Сталинграда В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Волгоградская область/Волгоград/Центральный район","revision":779549,"license":"CC BY-SA 4.0","image":"Зал Воинской Славы на Мамаевом кургане.jpg"},"ru-b7127184ead6-o3fdd7d68de64":{"name":"Памятник С.М. Кирову","kind":"architecture","lat":68.9690318,"lon":33.078804,"text":"Автор объекта: ск. З.И. Виленский. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Мурманская область/Мурманск","revision":747285,"license":"CC BY-SA 4.0","image":"Памятник С. М. Кирову в Мурманске.JPG"},"ru-0be84f75bbb5-o75bc152635a5":{"name":"Кинотеатр \"Октябрь\"","kind":"family","lat":44.201287,"lon":43.13391,"text":"Отдельно стоящее здание кинотеатра, сделанное по типичному советскому проекту, внутри - кафе, есть 3D-кинозал.","title":"Минеральные Воды","revision":761267,"license":"CC BY-SA 4.0","image":null},"ru-c52ea942555e-ofe54af6d46e2":{"name":"Памятник И.А. Крылову","kind":"architecture","lat":56.86088,"lon":35.893362,"text":"Автор объекта: ск-ры Д.В. Горлов, С.Д. Шапошников, арх. Н.В. Донских. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Тверская область/Тверь (часть 1)","revision":776054,"license":"CC BY-SA 4.0","image":"Памятник Крылову в Твери.jpg"},"msk-oaf916cbb9c92":{"name":"Горбатый мост","kind":"architecture","lat":55.755246,"lon":37.576699,"text":"В документах числится по Дружинниковской улице. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/За Садовым кольцом от Краснопресненской наб. до 1-й Тверской-Ямской","revision":783846,"license":"CC BY-SA 4.0","image":"Gorbaty Most v Moskve.jpg"},"msk-od1ab08664997":{"name":"Здание Ссудной казны","kind":"architecture","lat":55.76744816,"lon":37.60354068,"text":"Автор объекта: арх. В.А. Покровский. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/От Тверской до Цветного бульв.","revision":776230,"license":"CC BY-SA 4.0","image":"Российская ссудная казна 1.jpg"},"msk-ob2350bf7e907":{"name":"Памятник А.С. Пушкину","kind":"architecture","lat":55.765333,"lon":37.605472,"text":"Автор объекта: ск. А.М. Опекушин, арх. И.С. Богомолов, бронза, гранит. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/Тверская и 1-я Тверская-Ямская","revision":776469,"license":"CC BY-SA 4.0","image":"PushkinMskVblizi.jpg"},"msk-odc0c4a6e5f68":{"name":"Саввинское подворье","kind":"architecture","lat":55.76039804,"lon":37.61191297,"text":"Автор объекта: арх. И.С. Кузнецов. Архитектурный стиль: модерн. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/Тверская и 1-я Тверская-Ямская","revision":776469,"license":"CC BY-SA 4.0","image":"Moscow SavvinskePodvorye 7892.jpg"},"msk-o5f1fdf1a7a14":{"name":"Клуб завода «Каучук»","kind":"architecture","lat":55.73571255,"lon":37.57413882,"text":"Автор объекта: арх. К.С. Мельников. Архитектурный стиль: конструктивизм. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/От Садов. кольца до Фрунзенск., Лужнецк., Новодев., Саввинск., Ростов. и Смолен. наб.","revision":783257,"license":"CC BY-SA 4.0","image":"Moscow ClubKauchuk h42b.jpg"},"spb-ocd8b1344938f":{"name":"Буддийский храм","kind":"architecture","lat":59.98361,"lon":30.25583,"text":"Автор объекта: арх. Г.В. Барановский, арх. Н.М. Березовский. Архитектурный стиль: модерн. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Приморский район","revision":776987,"license":"CC BY-SA 4.0","image":"Buddhist temple Gunzechoinei01.jpg"},"spb-of5f160836b26":{"name":"Эрмитажный театр","kind":"theater","lat":59.942605,"lon":30.317808,"text":"Автор объекта: арх. Д. Кваренги, 1904 г., арх. Л.Н. Бенуа (интерьеры). В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Центральный район (часть 2)","revision":783019,"license":"CC BY-SA 4.0","image":"Spb 06-2012 Palace Embankment various 12.jpg"},"ekb-o486d90ff83a0":{"name":"Загородная дача архитектора М.П. Малахова","kind":"architecture","lat":56.83389,"lon":60.62364,"text":"Каменная копия 1975-1979 гг. Купол бельведера - оригинальный, сохранился от первоначальной постройки. В здании располагается Академия архитектуры В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Свердловская область/Екатеринбург (центр - часть 2)","revision":769971,"license":"CC BY-SA 4.0","image":"Загородная дача архитектора Малахова Луначарского 173а 100.jpg"},"spb-o9f11a64ae5fd":{"name":"Белая башня","kind":"architecture","lat":59.723526,"lon":30.390383,"text":"Автор объекта: арх. А.А. Менелас. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Пушкин (часть 2)","revision":780274,"license":"CC BY-SA 4.0","image":"Белая башня,Санкт-Петербург и Лен.область, Пушкин, пейзажная часть парка.JPG"},"ru-d177d438ea69-oc013ea0d0b74":{"name":"Кафе «Русколка»","kind":"coffee","lat":61.944502,"lon":30.578964,"text":"Продвинутая столовая самообслуживания с красиво приготовленной едой и симпатичным интерьером. Достаточно широкий выбор блюд европейской и карельской кухни, есть калитки и солянка с брусникой.","title":"Рускеала","revision":750162,"license":"CC BY-SA 4.0","image":null},"ru-9b0efbd022bb-o0b022fa3ca0e":{"name":"Лермонтовская галерея","kind":"architecture","lat":44.03662,"lon":43.08187,"text":"Лермонтовская галерея была построена в \"Цветнике\" в 1901 г. Она аналогична Пушкинской галерее в Железноводске. Левое крыло служило для отдыха в ненастье, а в правом располагался Казённый театр на 600 мест. На открытой площадке играл оркестр. Сейчас тут проводятся концерты, выставки.","title":"Пятигорск","revision":763172,"license":"CC BY-SA 4.0","image":"Lermontov Gallery in Pyatigorsk (October 2023) - 1.jpg"},"ru-9b0efbd022bb-oee43b82658b3":{"name":"Академическая галерея","kind":"architecture","lat":44.03974,"lon":43.08799,"text":"Елизаветинская галерея построена в 1847-1848 годах по проекту британского архитектора С.И. Уптона из белого машукского камня. В левом её крыле был устроен зал для отдыха и находился источник, в правом за аркой - Товиевские ванны. В 1925 году галерея получила своё нынешнее наименование в честь 200-летия Российской академии наук. Сейчас здесь находятся бюветы.","title":"Пятигорск","revision":763172,"license":"CC BY-SA 4.0","image":null},"ru-b28b6f6f1435-o78d592798579":{"name":"Театр металлургов","kind":"theater","lat":53.765926,"lon":87.09541,"text":"Автор объекта: арх-ры Е.И. Аппак, Г. Козель. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Кемеровская область/Новокузнецк","revision":782861,"license":"CC BY-SA 4.0","image":"Новокузнецк, Театр Металлургов, 1.jpg"},"spb-o9f5b11ec0714":{"name":"Константиновский дворец","kind":"museum","lat":59.853905,"lon":30.058401,"text":"Дворец начали строить ещё при Петре I, однако достраивали уже в середине XVIII в. под руководством Бартоломео Растрелли. Позднее дворец неоднократно переделывался другими известными архитекторами и использовался как загородная резиденция членов императорской семьи.","title":"Стрельна","revision":748973,"license":"CC BY-SA 4.0","image":"Константиновский Дворец.jpg"},"spb-o9afcdd5b972f":{"name":"«Токио-City»","kind":"food","lat":59.856306,"lon":30.0151,"text":"Сетевое заведение, широко распространившееся по Санкт-Петербургу и его окрестностям. Позиционирует себя как ресторан, однако по характеру меню, где представлены общеизвестные блюда русской, европейской и азиатской кухни, это скорее кафе с обслуживанием.","title":"Стрельна","revision":748973,"license":"CC BY-SA 4.0","image":null},"spb-oc6b1c7d901ce":{"name":"Ресторан «Стрельна»","kind":"coffee","lat":59.851146,"lon":30.060841,"text":"Ресторан с банным комплексом. Расположен практически напротив Константиновского дворца, и поэтому дорогой и очень безвкусно оформленный. Имеется летняя веранда с видом на парк и дворец.","title":"Стрельна","revision":748973,"license":"CC BY-SA 4.0","image":null},"ru-298ebb96d9c3-o769ab0fbbe8e":{"name":"Скала Петушок","kind":"walk","lat":44.62207,"lon":39.09177,"text":"Один из самых известных объектов кавказких предгорий: 28-метровая скала на реке Псекупс. Название она получила из-за того, что раньше гребень имел три зубца и напоминал петушиную голову.","title":"Горячий Ключ","revision":693056,"license":"CC BY-SA 4.0","image":null},"msk-oc438420a1b58":{"name":"Craft Republic","kind":"night","lat":55.7627,"lon":37.60636,"text":"Один из первых в Москве крафтовых пабов быстро стал клубом по интересам: бармены здесь не только наливают пиво, но и вступают с посетителями в жаркие споры о преимуществах и недостатках того или иного сорта. Постоянно обновляемая линейка разливного пива, необычные горячие закуски, неформальная обстановка.","title":"Москва/Тверская","revision":519696,"license":"CC BY-SA 4.0","image":null},"msk-of43b6e8cd8c9":{"name":"Парк Культуры","kind":"park","lat":55.735761,"lon":37.594776,"text":"Южная конечная пускового участка московского метро построена по проекту архитекторов Георгия Крутикова и В.С.Попова. Лестница в северном торце станции ведёт к выходу на внутренней стороне Садового кольца, две лестницы на южной стороне - вход и выход в вестибюль, совместный со станцией Кольцевой линии.","title":"Московский метрополитен","revision":313848,"license":"CC BY-SA 4.0","image":"Park kul'turi stantion.JPG"},"msk-od13de8c2b1f0":{"name":"Сад им. Баумана","kind":"park","lat":55.7672,"lon":37.6596,"text":"Один из крупнейших парков на северо-востоке центра Москвы. В него можно попасть как со стороны Новой Басманной, так и со стороны Старой Басманной улицы. Архитектурных достопримечательностей на территории парка немного — выделить можно только фонтан-василиск и памятник-бюст Н.Э. Бауману.","title":"Москва/Басманный район","revision":587461,"license":"CC BY-SA 4.0","image":"Новый год в саду Баумана -120.jpg"},"msk-od468cccf3937":{"name":"Памятник Ломоносову","kind":"architecture","lat":55.70119,"lon":37.52763,"text":"Памятник, посвящённый Михаилу Васильевичу Ломоносову, и построенный в 1953 году, расположен в центре площади Ломоносова между зданиями Химического и Физического факультетов МГУ.","title":"Москва/Воробьёвы горы","revision":545511,"license":"CC BY-SA 4.0","image":null},"msk-o323334d11234":{"name":"Парк «Сокольники»","kind":"park","lat":55.800278,"lon":37.674167,"text":"Парк площадью 600 гектаров получил своё название, как место соколиной охоты царей. Планировка парка оригинальна и представляет собой семь аллей-просек, расходящихся от Сокольничего круга - центра парка с танцплощадками, эстрадой, ресторанами. Каждая из аллей имеет своё «деревянное название»: Берёзовая, Кленовая, Вязовая и т.д.","title":"Москва/Сокольники","revision":519710,"license":"CC BY-SA 4.0","image":"SokolnikiFerrisWheel.JPG"},"ekb-o3d7948a79b42":{"name":"Своя компания","kind":"food","lat":56.9742,"lon":60.5768,"text":"Сетевой екатеринбургский ресторан с креативными блюдами и довольно гуманными ценами.","title":"Верхняя Пышма","revision":696452,"license":"CC BY-SA 4.0","image":null},"spb-o5e50ee294e1f":{"name":"Павильон «Вольер»","kind":"museum","lat":59.685613,"lon":30.456755,"text":"Автор объекта: арх. Ч. Камерон, 1806 г., арх. А.Н. Воронихин. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Павловск (парк)","revision":783255,"license":"CC BY-SA 4.0","image":"Павловск, Павловский парк. Павильон «Вольер» 3.jpg"},"spb-o2a8b46a37abb":{"name":"Павильон Катальной горки","kind":"architecture","lat":59.916526,"lon":29.744344,"text":"Автор объекта: арх. А. Ринальди, 1951-1959 гг. (реставрация), арх. М.М. Плотников. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Ломоносов (парк)","revision":779450,"license":"CC BY-SA 4.0","image":"Ораниенбаум 2006 06 01.jpg"},"ekb-of56b8a8f9ab4":{"name":"Памятник Татищеву и де Геннину","kind":"architecture","lat":56.83818,"lon":60.6057,"text":"Современный (1998) памятник основателям города, который горожане, не иначе как с чувством благодарности именитым предкам, называют «Бивис и Бадхет». Рядом с памятником обратите внимание на старую водонапорную башню (1880-е гг.) — самую симпатичную из старых построек Исторического сквера.","title":"Екатеринбург/Центр","revision":676135,"license":"CC BY-SA 4.0","image":"Памятник оснавателям Екатеринбурга - panoramio.jpg"},"ekb-o0724a8618b8f":{"name":"Памятник клавиатуре","kind":"architecture","lat":56.83234,"lon":60.60745,"text":"Глуповатое нагромождение камней в виде клавиш, некоторые из которых \"выпали\" и были унесены в неизвестном направлении.","title":"Екатеринбург/Центр","revision":676135,"license":"CC BY-SA 4.0","image":"RU Yekaterinburg Keyboard Monument.jpg"},"ekb-obf8364877c5d":{"name":"Дом Севастьянова","kind":"architecture","lat":56.83893,"lon":60.60593,"text":"Одно из самых вычурных сооружений Екатеринбурга, ставшее символом города. Рафинированная эклектика с элементами необарокко и готическо-мавританского стиля. Вообще говоря, здание построено ещё в нач.","title":"Екатеринбург/Центр","revision":676135,"license":"CC BY-SA 4.0","image":"Дом Севастьянова (окружной суд) Екатеринбург.jpg"},"ekb-o1cc15c4dea03":{"name":"Кафе «1991»","kind":"coffee","lat":56.8447,"lon":60.5923,"text":"Ресторан Ельцин-центра не имеет ничего общего с реальностью первого года независимой России и представляет собой обычное заведение в европейском стиле с приятной, хотя ничем специально не запоминающейся кухней. Местный хит — «блюда по рецептам Наины Иосифовны», супруги Бориса Ельцина: пельмени со щукой и черёмуховый торт.","title":"Екатеринбург/Центр","revision":676135,"license":"CC BY-SA 4.0","image":null},"ekb-o2a1727f785e4":{"name":"Поль Бейкери","kind":"coffee","lat":56.83998,"lon":60.61076,"text":"Большая кулинария, самообслуживание. Зал двухэтажный; особенно хорош верхний уровень, с которого через стекло можно наблюдать за снующими внизу людьми, машинами и всей городской жизнью.","title":"Екатеринбург/Центр","revision":676135,"license":"CC BY-SA 4.0","image":null},"ru-cf600ae8e376-o781bb8e629bd":{"name":"Ресторан Love Story","kind":"food","lat":54.665523,"lon":86.166851,"text":"Сердечки и античные руины на стенах — заведение выглядит провинциально, но не так пошло, как можно было бы предположить из названия. Противоречивые отзывы.","title":"Ленинск-Кузнецкий","revision":638097,"license":"CC BY-SA 4.0","image":null},"spb-oa3608f1f277f":{"name":"The Kitchen","kind":"food","lat":59.90568151145195,"lon":30.317405372557154,"text":"Ресторан состоит из нескольких небольших залов, имеет большую детскую комнату. В меню много интересных блюд. Недёшево, но вкусно.","title":"Санкт-Петербург/Московский проспект","revision":745825,"license":"CC BY-SA 4.0","image":null},"spb-oa68ebcb93939":{"name":"Express Trattoria","kind":"food","lat":59.86930283614254,"lon":30.34867732293205,"text":"Ресторан в ТРК «Питер Радуга» с настоящей итальянской кухней. Есть интересные блюда, которые в обычных итальянских ресторанах не встретишь.","title":"Санкт-Петербург/Московский проспект","revision":745825,"license":"CC BY-SA 4.0","image":null},"spb-o1508ff85de0f":{"name":"Компания Family","kind":"food","lat":59.8572481190976,"lon":30.321562666842837,"text":"Премиум-ресторан недалеко от Московской площади. Приятный персонал, разнообразное меню, есть большая детская комната.","title":"Санкт-Петербург/Московский проспект","revision":745825,"license":"CC BY-SA 4.0","image":null},"spb-o24a765307b5d":{"name":"Экзоопарк","kind":"family","lat":59.876341761181514,"lon":30.361754203583065,"text":"Довольно большой парк экзотических животных внутри ТРЦ «РИО». Представлены обезьяны, рыбы, птицы и другие животные, всего около 50 видов.","title":"Санкт-Петербург/Волково и Купчино","revision":660162,"license":"CC BY-SA 4.0","image":null},"spb-o38d27b59b403":{"name":"Семимостье","kind":"architecture","lat":59.920776,"lon":30.298648,"text":"Упражнение на ориентирование - если стоять в определенной точке, можно разглядеть вокруг семь мостов через каналы.","title":"Санкт-Петербург/Коломна","revision":518047,"license":"CC BY-SA 4.0","image":null},"spb-o26a4e4d3ed72":{"name":"Дежурные конюшни","kind":"architecture","lat":59.717429,"lon":30.399127,"text":"Автор объекта: арх. В.П. Стасов, арх. С.Л. Шустов. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Пушкин (часть 4)","revision":773976,"license":"CC BY-SA 4.0","image":"Пушкин. Дежурные конюшни06.jpg"},"spb-o1d3d54bab7d3":{"name":"Большая Оранжерея","kind":"architecture","lat":59.716004,"lon":30.401761,"text":"Автор объекта: арх. Ф.-Б. Растрелли, 1820-1828 гг., арх. В.П. Стасов, 1933-1934 гг., арх.-худ. В.И. Яковлев. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Пушкин (часть 4)","revision":773976,"license":"CC BY-SA 4.0","image":"Пушкин. Большая оранжерея02.jpg"},"ru-0839d751b940-o3349a6a16bf8":{"name":"Парк Победы","kind":"park","lat":51.96762,"lon":85.90552,"text":"Неожиданно крупный для столь маленького города воинский мемориал сооружён в 1977 году. Он состоит из массивных бетонных плит, образующих коридор перед центральной стелой: от этой композиции веет чем-то языческим.","title":"Горно-Алтайск","revision":648500,"license":"CC BY-SA 4.0","image":null},"ru-a309e4ce2f36-o685d34d9ba49":{"name":"Камская ГЭС","kind":"architecture","lat":58.1146187,"lon":56.3275909,"text":"Автор объекта: Б.К. Александров, Е. Попов, С. Корянский. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Пермский край/Пермь (часть 3)","revision":775496,"license":"CC BY-SA 4.0","image":"КамГЭС.jpg"},"ru-f05b2b62f54c-od0b5a5843609":{"name":"Михайловский пруд","kind":"park","lat":55.978592,"lon":37.152628,"text":"Пруд приятно разнообразит многоэтажную застройку в спальных районах новой части Зеленограда. На ведущей к пруду аллее установлены разножанровые городские скульптуры: \"мама с коляской\", \"девочка с собакой\", \"9 мая\" и отдыхающий на лавочке бронзовый архитектор - неформальный памятник И.А.Покровскому, автору многих проектов, создавших облик Зеленограда.","title":"Зеленоград","revision":762862,"license":"CC BY-SA 4.0","image":"Михайловский пруд, Зеленоград.jpg"},"ru-dee2e80ef2e1-o7ef0df7e14f5":{"name":"Александровский парк","kind":"park","lat":47.7074,"lon":40.209363,"text":"Городской парк — чуть ли не единственная зелёная зона в Шахтах, заложен ещё в дореволюционный период. Для районного центра парк необычно большой, в центре ухоженный, с каштановыми аллеями и розарием, а по краям немного запущенный.","title":"Шахты","revision":728302,"license":"CC BY-SA 4.0","image":null},"ru-8d0a05bf3b8a-oebf2c5612590":{"name":"Памятник Тысячелетию России","kind":"architecture","lat":58.521154,"lon":31.275232,"text":"Автор объекта: ск. М.О. Микешин. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Новгородская область/Великий Новгород (Кремль)","revision":777362,"license":"CC BY-SA 4.0","image":"InsideTheKremlin.jpg"},"ru-63fcf18a365e-ocd86f75bcd32":{"name":"Крокус Сити Океанариум","kind":"family","lat":55.818834,"lon":37.385873,"text":"Содержит 5000 рыб и водных животных, обитающих по всему миру. Есть дайвинг-центр, где можно понырять с рыбками и пройти по специальному маршруту длиной 2.5 км.","title":"Красногорск","revision":718127,"license":"CC BY-SA 4.0","image":"Красногорск. Крокус Сити Океанариум.jpg"},"ru-05a647ffb859-o85f2de67212a":{"name":"Ресторан «Обнинск»","kind":"food","lat":55.090397,"lon":36.602799,"text":"В монументальном здании 1957 года с колоннами расположены три банкетных зала, кафе «Счастье есть» и кондитерская. Среди гостей заведения когда-то были Юрий Гагарин и Владимир Высоцкий. Банкетные залы заняты проведением мероприятий, а в кафе можно поесть по средним ценам, с 12 до 16 ч. предлагают бизнес-ланчи.","title":"Обнинск","revision":737535,"license":"CC BY-SA 4.0","image":"Обнинск. Ресторан Обнинск.jpg"},"ru-05a647ffb859-o96fdf9c1fc74":{"name":"Ресторан «Диканька»","kind":"food","lat":55.110831,"lon":36.590422,"text":"Ресторан в стиле корчмы с широким выбором блюд русской и украинской кухни. Большие порции, вежливый персонал.","title":"Обнинск","revision":737535,"license":"CC BY-SA 4.0","image":null},"msk-o28ae95b1f6ba":{"name":"Парк Усадьбы Троицкое","kind":"park","lat":55.492348,"lon":37.301669,"text":"Расположен на месте старинной усадьбы Троицкое, которую в 1747 году купил чиновник Яков Евреинов и вскоре основал рядом с ней суконную фабрику (ставшую затем камвольной). В усадьбе в конце XVIII века были построены дома для проживания фабричного руководства, деревянная Троицкая церковь и разбит парк.","title":"Троицк (Москва)","revision":721790,"license":"CC BY-SA 4.0","image":"Троицк. Парк усадьбы Троицкое.jpg"},"ru-8effba3d4f82-o77252b03f748":{"name":"Coffee Like","kind":"coffee","lat":58.72979,"lon":50.18218,"text":"Киоск сетевой кофейни. Зимой согреют капучино халва-черёмуха, глинтвейн джекфрут, горячий шоколад, лавандовый раф и чай. Летом охладят эспрессо-тоник, классический мохито и милкшейк со вкусом бананового бисквита и клубники. В наличии десерты, леденцы-сердечки, ореховые конфеты, шоколад и печенье.","title":"Слободской","revision":777266,"license":"CC BY-SA 4.0","image":null},"spb-of828cd0db732":{"name":"Мариинский театр","kind":"theater","lat":59.925556,"lon":30.296111,"text":"Автор объекта: арх. А.К. Кавос, 1883-1886 гг., 1894 г., арх. В.А. Шретер. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Адмиралтейский район (часть 6)","revision":774990,"license":"CC BY-SA 4.0","image":"Mariinsky Theatre, 2004.jpg"},"spb-o775f319e1955":{"name":"Особняк Е.М. Бутурлиной","kind":"architecture","lat":59.946858,"lon":30.345147,"text":"Автор объекта: арх. Г.А. Боссе, 1920-е гг.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Центральный район (часть 8)","revision":783810,"license":"CC BY-SA 4.0","image":"Чайковского, 10 02.jpg"},"ru-86e5bae4ef58-o20e89343dee1":{"name":"Памятник С. А. Есенину","kind":"architecture","lat":54.63527,"lon":39.742285,"text":"Датировка в каталоге наследия: 1975. Автор объекта: ск. А.П. Кибальников, арх. Р.А. Бегунц.","title":"Культурное наследие России/Рязанская область/Рязань (часть 2)","revision":750851,"license":"CC BY-SA 4.0","image":"Ryazan Yesenin 019 7021.JPG"},"msk-o2fc3ccc8ef5e":{"name":"Дом-музей В.М. Васнецова","kind":"museum","lat":55.77674,"lon":37.62608839,"text":"Дом-мастерская, в котором жил и работал Виктор Михайлович Васнецов в 1894-1926 гг. В доме - музей В.М. Васнецова Автор объекта: М.Е. Приёмышев, В.М. Васнецов. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Москва/Центральный округ/За Садовым кольцом от Олимпийского просп. до просп. Мира","revision":770319,"license":"CC BY-SA 4.0","image":"Moscowm, Vasnetsov House 01.jpg"},"ru-bb035cc31dc2-o7b865676bea8":{"name":"Синагога","kind":"architecture","lat":53.183977,"lon":50.102489,"text":"Автор объекта: арх. З.В. Клейнерман. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Самарская область/Самара (часть 4)","revision":781502,"license":"CC BY-SA 4.0","image":"S Sinagoga.jpg"},"spb-o5b10da4d1dcf":{"name":"Нарышкин бастион","kind":"architecture","lat":59.948379,"lon":30.317746,"text":"Автор объекта: арх. Д. Трезини, 1780-1782 гг., 1840-1890-е гг.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Петроградский район (часть 7)","revision":779448,"license":"CC BY-SA 4.0","image":"Башня флажная (2).jpg"},"spb-o6963b0e494e3":{"name":"Тюрьма Трубецкого бастиона","kind":"museum","lat":59.948416,"lon":30.313307,"text":"Автор объекта: инж. К.П. Андреев, инж. А.М. Пасыпкин. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Петроградский район (часть 7)","revision":779448,"license":"CC BY-SA 4.0","image":"Тюрьма Трубецкого бастиона вход.jpg"},"spb-oe6846cff1d71":{"name":"Инженерный дом","kind":"museum","lat":59.950173,"lon":30.319149,"text":"Автор объекта: арх. И.Н. Бенуа (реставрация). В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Петроградский район (часть 7)","revision":779448,"license":"CC BY-SA 4.0","image":"Инженерный дом.JPG"},"spb-o55a73c2215ba":{"name":"Комендантский дом","kind":"architecture","lat":59.949541,"lon":30.316585,"text":"Автор объекта: арх. Д. Трезини (проект), 1874 г., 1892 г.. В каталоге отмечен охранный статус памятника.","title":"Культурное наследие России/Санкт-Петербург/Петроградский район (часть 7)","revision":779448,"license":"CC BY-SA 4.0","image":"Петропавловская крепость. Комендантский дом03.JPG"}};
